const top_fiora = {
  champion: '피오라',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '가렌이 (Q)\'결정타\'로 이동 속도를 높여 접근하며 침묵을 거는 것을 조심하세요. (Q)\'찌르기\'로 가렌의 체력을 깎으며 거리를 조절하되, (P)\'인내심\'은 잠시 피해를 받지 않으면 회복되니 주기적으로 견제를 넣어 회복을 끊으세요.', lv3: '가렌이 (E)\'심판\'을 돌리며 들어올 때 (W)\'응수\'로 (E)\'심판\'과 (Q)\'결정타\'의 공격을 막아낼 수는 있지만, 가렌에게는 이동 불가 효과가 없어서 기절은 나오지 않아요. (W)\'용기\'로 보호막과 강인함을 켰을 때는 (E)\'대가의 검술\'을 아끼고 딜교환을 미루세요. (W)\'용기\'가 끝난 뒤 (Q)\'찌르기\'로 진입해 딜교환을 주도하세요.', lv6: '가렌의 (R)\'데마시아의 정의\'는 잃은 체력에 비례한 고정 피해라 체력이 빠지면 위험하니 즉시 거리를 벌리세요. (R)\'대결투\'는 급소 네 군데를 드러내 최대 체력 비례 고정 피해를 주니 가렌의 체력이 빠졌을 때 시작하세요. 가렌은 (Q)\'결정타\'로 따라붙을 수 있으니 라인을 너무 밀어 넣지 마세요.', item: '첫 코어 아이템으로 몰락한 왕의 검을 가고 신발은 가렌의 물리 피해를 줄여주는 판금 장화를 선택하세요. 몰락한 왕의 검의 생명력 흡수로 전투를 지속하며 가렌을 압박할 수 있어요.', spell: '점멸과 점화를 추천해요. 점화로 가렌의 (P)\'인내심\' 회복을 억제하며 (R)\'대결투\'로 킬을 노리기 편해요.' },
    '갱플랭크': { lv1: '갱플랭크는 (Q)\'혀어어어업상\'으로 원거리 견제를 하지만 근접전은 약해요. 이 스킬은 대상 지정이라 미니언 뒤에 숨어도 맞으니, 적절한 타이밍에 (Q)\'찌르기\'로 진입해 빠르게 딜교환을 하세요. (P)\'불의 심판\'이 묻은 평타를 너무 많이 맞으면 손해이니 짧게 치고 빠지는 것이 좋아요.', lv3: '(E)\'화약통\'이 터지면 둔화가 걸리니 통 근처에서 싸우지 말고 (W)\'응수\'로 상대의 공격이나 둔화 효과를 막아내세요. 갱플랭크가 (W)\'괴혈병 치료\'를 사용해 군중 제어 효과를 제거하면 체력까지 회복하니, 이 스킬이 빠진 것을 확인하고 (E)\'대가의 검술\'로 강하게 압박하세요. (Q)\'찌르기\'로 급소를 빠르게 찌르며 이동 속도를 높여 (E)\'화약통\' 범위에서 벗어나세요.', lv6: '(R)\'포탄 세례\' 장판 위에서는 이동 속도가 느려져 (R)\'대결투\'의 급소를 찌르기 어려우니 장판 밖으로 빠르게 피하세요. 갱플랭크가 (W)\'괴혈병 치료\'로 체력을 회복하기 전에 (R)\'대결투\'로 급소를 빠르게 가격하며 몰아치세요. (R)\'포탄 세례\'는 맵 어디서든 날아오니 라인을 너무 밀지 말고 적당히 당겨서 정글의 개입을 기다리세요.', item: '첫 코어는 굶주린 히드라로 가서 광역 피해와 흡혈로 라인 관리와 지속 교전을 함께 챙기세요. 신발은 갱플랭크의 기본 공격 피해를 줄여 주는 판금 장화를 맞추세요.', spell: '점멸과 점화를 추천해요. (W)\'괴혈병 치료\'의 체력 회복을 점화로 억제해야 (R)\'대결투\' 이후 확실하게 마무리할 수 있어요.' },
    '그라가스': { lv1: '1~2레벨 구간에는 그라가스의 (Q)\'술통 굴리기\' 둔화와 견제를 주의하며 (P)\'서비스 시간\' 회복을 고려해야 해요. (P)\'치명적인 검무\'의 급소를 챙기며 체력 관리에 집중하고 거리 조절을 잘하세요. 술통이 터지는 위치를 보고 피해가 겹치지 않게 막타를 챙기세요.', lv3: '그라가스가 (E)\'몸통 박치기\'로 에어본을 노릴 때 (W)\'응수\'로 막아내면 기절을 시킬 수 있어요. (W)\'취중 분노\'를 켠 상태에서는 피해가 줄어드니 그 타이밍에는 억지로 싸우지 마세요. (W)\'응수\'로 이동 불가 효과를 막은 뒤 (Q)\'찌르기\'로 빠르게 파고들어 딜교환을 하세요.', lv6: '(R)\'대결투\'를 사용해 급소를 가격하며 몰아칠 때 그라가스의 (R)\'술통 폭발\'에 밀려나지 않도록 주의하세요. 그라가스가 (E)\'몸통 박치기\'를 먼저 사용했다면 (Q)\'찌르기\'로 진입해 (R)\'대결투\'의 치유 효과를 활용해 보세요. 라인을 밀어 두면 정글러의 개입이 있을 수 있으니 시야를 확인하세요.', item: '굶주린 히드라를 첫 코어로 선택해 생명력 흡수를 챙기세요. 신발은 마법 저항력과 강인함이 있는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 그라가스의 (P)\'서비스 시간\' 회복을 억제하고 킬각을 잡기 편해요.' },
    '그웬': { lv1: '그웬은 (P)\'가위 난도질\'로 체력을 회복하며 평타 싸움을 유도하니 1~2레벨에 길게 싸우지 마세요. (Q)\'찌르기\'로 급소만 빠르게 치고 빠지며 피해를 최소화하세요. 그웬이 (Q)\'싹둑싹둑!\'을 쓸 때 중앙의 고정 피해를 피하도록 옆으로 움직이세요.', lv3: '(W)\'신성한 안개\' 밖에서는 그웬을 지정할 수 없으니 안개 속으로 과감히 들어가거나 안개가 사라질 때까지 기다리세요. (E)\'돌격가위\'는 이동 불가 효과가 없어서 (W)\'응수\'로 기절시킬 수 없으니, (Q)\'싹둑싹둑!\'의 중심을 피해 (E)\'대가의 검술\'로 빠르게 급소를 가격하세요. 상대가 가위질을 모두 소모한 빈틈에 (Q)\'찌르기\'로 진입해 딜교환을 마무리하세요.', lv6: '(R)\'바느질\'의 둔화에 걸리면 급소를 치기 어려우니 바늘의 궤적을 피해 움직이며 (R)\'대결투\'를 사용하세요. (W)\'신성한 안개\'가 켜진 상태에서는 안개 밖에서 그웬을 대상으로 지정할 수 없으니 안개가 사라진 뒤에 (R)\'대결투\'를 쓰세요. (W)\'응수\'는 그웬의 결정적인 공격을 막는 데 아껴 두세요.', item: '몰락한 왕의 검과 헤르메스의 발걸음을 추천해요. 몰락한 왕의 검은 적의 현재 체력에 비례한 피해로 그웬의 체력을 깎기 좋고, 헤르메스의 발걸음은 마법 저항력으로 그웬의 마법 피해를 줄여줘요.', spell: '점멸과 점화를 추천해요. 그웬이 (P)\'가위 난도질\'로 회복하는 양을 점화로 억제해야 킬각을 잡기 편해요.' },
    '나르': { lv1: '나르는 (Q)\'부메랑 던지기\'로 둔화를 걸며 멀리서 견제하니 부메랑의 궤적을 피해 맞는 횟수를 줄이세요. (Q)\'찌르기\'로 빠르게 접근해 짧은 딜교환을 하고 뒤로 빠지며 상대의 분노 수급을 늦춰야 해요. (Q)\'부메랑 던지기\'를 던진 직후가 빈틈이니 이때 적극적으로 평타를 섞어 공격하세요.', lv3: '(E)\'폴짝\'으로 진입할 때 (W)\'응수\'로 공격을 막을 수는 있지만 나르에게는 이동 불가 효과가 없어 기절은 나오지 않아요. (E)\'대가의 검술\'의 빠른 공격 속도로 급소를 빠르게 쳐내고 (Q)\'찌르기\'로 추격하며 압박하세요. (W)\'슝슝\'의 추가 피해가 들어오는 세 번째 공격 타이밍에는 짧게 거리를 벌려 피해를 줄이세요.', lv6: '메가 나르의 (R)\'나르!\'는 벽에 부딪히면 기절시키니 벽 근처에서 싸우지 않도록 주의하세요. (W)\'쿵쾅\'의 기절 범위 밖에서 움직이다가 (R)\'대결투\'를 사용해 급소를 빠르게 공략하며 고정 피해를 입히세요. 나르가 메가 나르로 변신하기 전 작은 형태일 때 (Q)\'찌르기\'와 평타로 빠르게 킬각을 잡으세요.', item: '첫 코어는 굶주린 히드라로 가서 광역 피해와 흡혈로 라인 관리와 지속 교전을 함께 챙기세요. 신발은 나르의 기본 공격 피해를 줄여주는 판금 장화가 효율적이에요.', spell: '점멸과 순간이동을 추천해요. 점멸로 (R)\'대결투\'에 진입할 거리를 만들고 순간이동으로 라인 복귀를 빠르게 하기 위해서예요.' },
    '나서스': { lv1: '1~2레벨 구간에는 나서스가 (Q)\'흡수의 일격\'으로 미니언 스택을 쌓지 못하도록 (Q)\'찌르기\'로 견제하며 거리를 조절하세요. 나서스가 미니언을 치려 할 때 짧게 딜교환을 하고 빠지면 나서스의 성장을 늦출 수 있어요. 무리하게 평타 싸움을 하기보다는 미니언을 함께 받아먹으며 체력을 관리하세요.', lv3: '나서스가 (W)\'쇠약\'을 사용하여 이동 속도와 공격 속도를 낮출 때 (W)\'응수\'로 대응하거나 적절한 타이밍에 급소를 노려야 해요. (E)\'대가의 검술\'로 둔화를 걸고 (P)\'치명적인 검무\'의 급소를 빠르게 가격하여 피해를 입히세요. (E)\'영혼의 불길\'이 깔린 구역에서는 방어력이 감소하니 그 위에서 오래 머물지 마세요.', lv6: '나서스가 (R)\'사막의 분노\'를 켜면 체력과 공격 범위가 늘어나니 궁극기 지속시간 중에는 무리한 교전을 피하세요. (R)\'대결투\'를 사용하여 급소를 모두 가격하고, 나서스의 공격을 (W)\'응수\'로 막아내며 딜교환을 진행하세요. 라인을 빠르게 밀어 넣어서 나서스가 (Q)\'흡수의 일격\'으로 스택을 쌓기 어렵게 만드세요.', item: '몰락한 왕의 검을 첫 코어로 선택하여 나서스의 체력을 깎고 전투를 지속하세요. 신발은 나서스의 (Q)\'흡수의 일격\'과 기본 공격 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 나서스의 (P)\'영혼의 포식자\'를 통한 생명력 흡수를 억제하고 마무리 피해를 입히세요.' },
    '녹턴': { lv1: '녹턴이 (Q)\'황혼의 인도자\'를 던져 견제하면 궤적 위에서 녹턴의 이동 속도와 공격력이 오르니 궤적 위에서는 싸우지 말고 (Q)\'찌르기\'로 짧게 접근하세요. 초반에는 무리하게 딜교환을 하기보다 미니언을 챙기며 상대의 이동 속도가 올라가는 구간을 조심하세요. (P)\'치명적인 검무\'의 급소를 챙기며 체력을 관리하는 것이 중요해요.', lv3: '녹턴이 (W)\'어둠의 장막\'으로 스킬을 막으려 할 때 무리하게 스킬을 낭비하지 마세요. 녹턴이 (E)\'말할 수 없는 공포\'를 사용하여 연결을 시도하면 (W)\'응수\'를 사용해 공포를 막아내고 기절을 노려요. (E)\'대가의 검술\'을 활용해 짧고 강력한 딜교환을 진행해요.', lv6: '녹턴이 (R)\'피해망상\'을 사용하여 시야를 차단하고 날아올 때를 대비해 (W)\'응수\'를 아껴두세요. (R)\'대결투\'를 사용해 급소를 모두 가격하며 전투를 이끌어가는 것이 좋아요. 정글러의 개입이 쉬워지는 시기이므로 라인을 너무 깊게 밀기보다 시야 확보에 신경 써요.', item: '판금 장화와 굶주린 히드라를 선택해요. 상대의 기본 공격 피해를 줄이고 생명력 흡수를 통해 전투 지속력을 높여요.', spell: '점멸과 점화를 추천해요. 녹턴의 (P)\'그림자 칼날\'은 기본 공격으로 체력을 회복하니 점화로 회복을 줄이고 마무리 피해를 넣기 위해서예요.' },
    '다리우스': { lv1: '다리우스는 (P)\'과다출혈\'이 쌓일수록 강해지니 1~2레벨 구간에서 무리한 맞딜은 피하세요. (Q)\'학살\'의 도끼날에 맞으면 체력을 회복하므로 도끼자루 사거리에서 싸우며 (Q)\'찌르기\'로 급소를 노리세요.', lv3: '다리우스가 (E)\'포획\'을 사용해 끌어당기려 할 때 거리 조절을 하거나 (W)\'응수\'를 활용해 대응하세요. (E)\'포획\'이 빠진 타이밍에 (E)\'대가의 검술\'로 급소를 빠르게 가격하며 짧게 딜교환을 하세요.', lv6: '다리우스의 (R)\'녹서스의 단두대\'는 (P)\'과다출혈\' 중첩이 많을수록 강력하니 체력이 낮을 때는 주의하세요. (R)\'대결투\'를 사용해 급소를 모두 가격하며 다리우스의 공격을 버텨내면 좋아요.', item: '판금 장화와 굶주린 히드라를 추천해요. 판금 장화는 기본 공격으로 받는 피해량을 줄여주고 굶주린 히드라는 생명력 흡수로 라인 유지력을 도와줘요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'학살\'의 체력 회복을 줄이고, 점멸로 (E)\'포획\'의 사거리 밖으로 거리를 조절하세요.' },
    '라이즈': { lv1: '라이즈는 (Q)\'과부하\'를 직선으로 쏘며 견제하지만 첫 번째 적에게만 맞으므로 미니언 뒤에 서서 피해를 줄이세요. 1~2레벨에는 (Q)\'찌르기\'로 무리하게 진입하기보다 상대의 마나 소모를 유도하며 버티는 것이 좋아요. 막타를 치러 오는 순간에 평타로 급소를 쳐서 체력을 회복하며 상대의 압박을 받아내세요.', lv3: '(E)\'주문 전이\' 표식이 남은 상태에서 (W)\'룬 감옥\'에 맞으면 속박되니, 라이즈가 구체를 던진 직후에는 (W)\'응수\'를 사용해 속박을 막고 기절시키세요. 라이즈의 CC기가 빠진 틈을 타 (Q)\'찌르기\'로 빠르게 접근해 (E)\'대가의 검술\'로 두 번의 공격을 모두 맞히면 강하게 압박할 수 있어요. 상대의 스킬 쿨타임을 확인하며 짧은 딜교환을 반복해 체력을 깎으세요.', lv6: '(R)\'대결투\'를 사용해 급소를 모두 터뜨리면 고정 피해를 입혀 라이즈를 빠르게 처치할 수 있어요. 라이즈가 (R)\'공간 왜곡\'으로 아군을 불러오거나 도망칠 수 있으니, 정글러의 위치를 확인하며 라인을 관리하세요. (W)\'응수\'로 (W)\'룬 감옥\'을 무력화한 뒤 (R)\'대결투\'를 연계하면 라이즈가 도망가기 전에 승부를 보기 편해요.', item: '삼위일체와 헤르메스의 발걸음을 추천해요. 삼위일체는 공격력과 체력을 높여주고, 헤르메스의 발걸음은 마법 저항력과 강인함으로 (W)\'룬 감옥\'의 지속시간을 줄여줘요.', spell: '점멸과 순간이동을 추천해요. 라이즈가 (R)\'공간 왜곡\'으로 빠르게 합류하거나 로밍을 갈 때 유연하게 대응하기 위해 필요해요.' },
    '럼블': { lv1: '럼블은 (Q)\'화염방사기\'로 근접 거리에서 강한 마법 피해를 입히며 라인을 압박해요. 럼블의 열기가 높아져 위험 상태가 되면 피해가 더 커지니 무리하게 붙지 말고 거리를 유지하세요. (Q)\'찌르기\'를 활용해 짧게 딜교하며 미니언을 챙기는 것이 좋아요.', lv3: '럼블이 (E)\'전기 작살\'을 맞히면 둔화와 마법 저항력 감소가 걸리니 작살을 쌓지 못하게 거리를 조절하세요. 럼블에게는 이동 불가 효과가 없어서 (W)\'응수\'로 기절을 노리기보다 (Q)\'화염방사기\'가 시작될 때 피해를 막는 용도로 쓰세요. 열기가 쌓여 위험 상태가 되기 전에 (E)\'대가의 검술\'로 둔화를 걸며 급소를 공략하세요.', lv6: '럼블의 (R)\'이퀄라이저 미사일\'이 깔리면 불타는 궤적 위에 머물지 말고 즉시 밖으로 벗어나세요. 럼블이 과열되어 스킬을 쓸 수 없는 틈을 타 (R)\'대결투\'를 켜고 급소를 빠르게 가격하면 킬을 노릴 수 있어요. 궤적이 한동안 남으니 정글러의 위치를 확인하며 싸우세요.', item: '첫 코어로 굶주린 히드라를 올려서 라인 유지력과 공격력을 챙기세요. 신발은 럼블의 마법 피해와 군중 제어를 줄여주는 헤르메스의 발걸음을 선택해요.', spell: '점멸과 점화를 추천해요. 럼블의 (W)\'고철 방패\'는 피해를 흡수하니 점멸로 거리를 좁혀 보호막이 사라진 타이밍에 점화로 마무리 피해를 더하세요.' },
    '레넥톤': { lv1: '레넥톤은 (Q)\'양떼 도륙\'으로 피해를 입히고 체력을 회복하며 초반에 강하게 압박해요. 1~2레벨에는 (Q)\'찌르기\'로 급소를 찔러 짧게 딜교환하고 빠르게 빠지는 것이 중요해요. 레넥톤의 분노가 쌓이기 전까지는 정면 승부를 피하고 거리 조절에 신경 쓰세요.', lv3: '레넥톤이 (E)\'자르고 토막내기\'로 진입해 (W)\'무자비한 포식자\'로 기절시키려 할 때 (W)\'응수\'로 막아 기절시키세요. (W)\'무자비한 포식자\'가 빠진 상태라면 (E)\'대가의 검술\'과 평타를 활용해 빠르게 급소를 공략하고 빠지세요. 분노가 많이 쌓였을 때의 (W)\'무자비한 포식자\'는 기절 시간이 더 길어지니 더욱 주의해서 반응하세요.', lv6: '(R)\'강신\'을 사용한 레넥톤은 추가 체력을 얻고 분노를 빠르게 수급하므로 정면 대결은 신중하게 결정하세요. (R)\'대결투\'를 켜고 급소를 빠르게 공략하되, 상대의 (W)\'무자비한 포식자\'를 (W)\'응수\'로 받아내면 킬각을 잡기 쉬워요. 라인 관리 시 레넥톤의 돌진 거리를 계산해 정글러의 개입에 대비하세요.', item: '첫 코어는 굶주린 히드라로 가서 광역 피해와 흡혈로 라인 관리와 지속 교전을 함께 챙기세요. 신발은 레넥톤의 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 점화로 레넥톤의 (Q)\'양떼 도륙\' 회복량을 줄여야 교전에서 앞설 수 있어요.' },
    '렝가': { lv1: '수풀 근처에 가지 말고 거리 조절을 하며 (Q)\'찌르기\'로 급소를 가격해 체력을 회복하세요. 상대가 (Q)\'포악함\'을 쓰며 진입하려고 하면 뒤로 물러나며 피해를 최소화해요. 첫 웨이브에서는 무리하게 붙지 말고 거리 유지를 우선하세요.', lv3: '최대 야성으로 강화된 (E)\'올가미 투척\'은 속박을 거니 이때 (W)\'응수\'로 막아내어 기절시킨 뒤 딜교환을 시작하세요. (E)\'대가의 검술\'로 빠르게 두 번 공격하여 피해를 주고 (Q)\'찌르기\'로 급소를 쳐서 체력을 회복해요. 상대가 (W)\'전투의 포효\'로 체력을 회복하기 전에 빠르게 딜교환을 마치고 빠지세요.', lv6: '상대가 (R)\'사냥의 전율\'을 쓰고 위장 상태로 접근할 때 주의하며 (R)\'대결투\'를 켜서 급소를 빠르게 가격하세요. 수풀 근처에서 라인을 형성하면 갑작스러운 도약 공격을 받을 수 있으니 라인 관리에 신경 써요. 정글러가 개입하기 좋은 구도이므로 (W)\'응수\'를 아껴두었다가 결정적인 진입 스킬을 막으세요.', item: '판금 장화와 삼위일체를 가세요. 판금 장화는 상대의 기본 공격 피해를 줄여주고 삼위일체는 공격력과 체력을 높여 딜교환에 도움을 줘요.', spell: '점멸과 점화를 추천해요. 점화는 상대의 (W)\'전투의 포효\' 회복량을 줄이고 킬각을 잡는 데 유용해요.' },
    '리븐': { lv1: '리븐은 (Q)\'부러진 날개\'로 빠르게 접근하며 (P)\'룬 검\' 추가 피해를 입히는 구간이 강해요. 1~2레벨에는 무리하게 붙지 말고 (Q)\'찌르기\'로 거리 조절을 하며 리븐의 돌진을 경계하세요. (P)\'치명적인 검무\'의 급소를 치며 체력을 관리하는 것이 중요해요.', lv3: '리븐이 (W)\'기 폭발\'로 기절을 노릴 때 (W)\'응수\'로 이를 막아내면 역전의 기회를 잡을 수 있어요. 리븐의 (Q)\'부러진 날개\' 마지막 타격이 적을 밀쳐내기 전에 (E)\'대가의 검술\'을 사용해 딜교환을 시도하세요. 리븐의 스킬이 빠진 뒤에 (Q)\'찌르기\'를 활용해 급소를 노려야 해요.', lv6: '리븐이 (R)\'추방자의 검\'을 활성화하면 공격 사거리가 늘어나니 주의하며 (R)\'대결투\'를 사용하세요. (R)\'대결투\'로 급소를 빠르게 가격해 고정 피해를 입히고 피를 회복하며 싸워야 해요. 리븐이 스킬을 쏟아부은 직후에 (Q)\'찌르기\'로 진입하면 킬을 따내기 쉬워요.', item: '몰락한 왕의 검을 첫 코어로 가서 공격 속도와 생명력 흡수를 챙기세요. 신발은 리븐의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 리븐을 빠르게 마무리하기 위해서예요.' },
    '리산드라': { lv1: '리산드라는 (Q)\'얼음 파편\'을 통해 멀리서 견제하며 둔화를 걸 수 있으니 주의해야 해요. 1~2레벨에는 (Q)\'찌르기\'를 활용해 급소를 노리며 최대한 짧게 교환하세요. 미니언 사이에서 (Q)\'얼음 파편\'의 둔화 범위를 피해 파밍하는 것이 중요해요.', lv3: '리산드라가 (W)\'서릿발\'로 발을 묶으려 할 때 (W)\'응수\'를 사용하여 군중 제어 효과를 막아내세요. (W)\'응수\'로 기절을 성공시킨 뒤 (E)\'대가의 검술\'을 켜고 급소를 공격해 딜교환을 이어가세요. 리산드라가 (E)\'얼음갈퀴 길\'로 도망가지 못하도록 위치를 잘 잡아야 해요.', lv6: '리산드라가 자신에게 (R)\'얼음 무덤\'을 사용해 무적 상태가 되면 무리하게 공격하지 말고 기다리세요. 리산드라가 나에게 (R)\'얼음 무덤\'을 사용해 기절시키면 정글러의 개입이 쉬우니 거리를 조절해야 해요. (R)\'대결투\'를 켜서 급소를 모두 가격하며 체력을 회복하고 고정 피해를 입히세요.', item: '첫 코어 아이템으로 몰락한 왕의 검을 구매해 생명력 흡수를 확보하세요. 신발은 리산드라의 마법 피해를 견디기 위해 헤르메스의 발걸음을 선택하세요.', spell: '점멸과 점화를 추천해요. 점화는 리산드라가 (R)\'얼음 무덤\'으로 체력을 회복할 때 이를 억제하고 마무리하는 용도로 사용하세요.' },
    '마스터이': { lv1: '1~2레벨에는 마스터 이의 (P)\'2연속 공격\'으로 인한 평타 피해가 강하니 거리를 조절하며 (Q)\'찌르기\'로 급소를 노려보세요. 마스터 이가 웨이브를 먹으러 올 때 (P)\'치명적인 검무\'의 급소를 가격해 체력을 회복하며 버텨야 해요.', lv3: '마스터 이가 (Q)\'일격 필살\'을 사용해 대상으로 지정할 수 없는 상태가 되면 (W)\'응수\'를 아껴 두었다가 돌아온 뒤에 사용하세요. 마스터 이가 (W)\'명상\'을 사용하여 체력을 회복하는 동안에는 무리하게 딜교환을 하지 마세요. (E)\'대가의 검술\'로 둔화를 걸고 (Q)\'찌르기\'를 맞춰 급소를 공략하세요.', lv6: '마스터 이가 (R)\'최후의 전사\'를 사용하면 둔화에 면역이 되니 (E)\'대가의 검술\'의 둔화 효과를 기대하기 어려워요. (R)\'대결투\'를 사용해 급소를 모두 가격하여 고정 피해를 입히고 체력을 회복하세요. 마스터 이가 킬을 통해 (R)\'최후의 전사\' 지속시간을 늘리지 못하도록 라인 관리에 신경 써야 해요.', item: '첫 코어로 몰락한 왕의 검을 선택해 전투를 지속하세요. 신발은 마스터 이의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 마스터 이가 (W)\'명상\'을 사용하여 체력을 회복할 때 점화로 회복 효과를 감소시켜야 해요.' },
    '마오카이': { lv1: '마오카이가 (E)\'묘목 던지기\'를 수풀에 깔아두면 접근할 때 폭발 피해와 둔화를 입으니 주의하세요. 1~2레벨에는 마오카이가 (Q)\'덤불 주먹\'으로 뒤로 밀어내며 딜교를 시도할 때 (Q)\'찌르기\'를 활용해 급소를 노려 보세요. 마오카이의 (P)\'마법 흡수\' 회복을 의식하며 짧게 딜교환을 한 뒤 거리를 조절하는 것이 좋아요.', lv3: '마오카이가 (W)\'뒤틀린 전진\'으로 달려들어 속박하려 할 때 (W)\'응수\'를 사용하여 이동 불가 효과를 막고 기절을 노리세요. 마오카이가 (Q)\'덤불 주먹\'을 쓰기 전에 먼저 다가가 (E)\'대가의 검술\'로 둔화를 걸며 딜교를 시작하는 것이 편해요. (E)\'묘목 던지기\'의 둔화 범위를 확인하며 (Q)\'찌르기\'로 빠르게 급소를 타격하세요.', lv6: '마오카이가 (R)\'대자연의 마수\'를 사용하면 거대한 벽이 다가오며 속박하니 벽이 오는 길 위에서 싸우지 말고 옆으로 피하세요. (R)\'대결투\'를 사용해 급소를 모두 가격하면 마오카이의 체력을 깎고 치유를 얻을 수 있어요. 마오카이의 궁극기가 빠진 뒤에 (W)\'응수\'로 받아치며 적극적으로 킬각을 잡으세요.', item: '마오카이의 체력을 깎고 지속 싸움을 이끌기 위해 몰락한 왕의 검을 첫 코어로 가세요. 신발은 마법 피해를 줄이고 강인함을 얻을 수 있는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 마오카이를 상대로 (R)\'대결투\'를 활용해 빠르게 처치하고 킬을 챙기기에 좋아요.' },
    '말자하': { lv1: '말자하의 (P)\'공허 태세\'가 켜져 있으면 받는 피해가 줄어드니 (Q)\'찌르기\'나 기본 공격으로 이 효과를 미리 벗겨 두세요. (Q)\'공허의 부름\' 투사체가 날아올 때는 위치를 옮겨 침묵에 걸리지 않도록 주의하며 라인을 관리해요. 1~2레벨에는 말자하의 견제가 강하므로 무리하게 진입하지 말고 거리를 유지하며 경험치를 챙겨요.', lv3: '(E)\'재앙의 환상\'에 걸리면 (W)\'공허의 무리\'가 몰려와 지속 피해가 커지니 (E)\'대가의 검술\'로 빠르게 딜교환을 하고 빠져나오세요. (Q)\'공허의 부름\'은 침묵이라 (W)\'응수\'로 기절을 노리기는 어려우니 투사체를 피한 뒤 들어가세요. (P)\'공허 태세\'가 깨진 타이밍을 노려 (Q)\'찌르기\'와 기본 공격으로 급소를 타격하며 압박하세요.', lv6: '말자하의 (R)\'황천의 손아귀\'는 제압이라 정화로 풀 수 없으니 (W)\'응수\'를 아껴두었다가 제압을 막아내는 용도로 사용하세요. (R)\'대결투\'를 사용하여 모든 급소를 빠르게 가격하면 고정 피해로 말자하를 압박할 수 있어요. 말자하가 (E)\'재앙의 환상\'을 유지하며 라인을 밀면 포탑 근처에서 정글러의 개입을 조심하며 싸워요.', item: '굶주린 히드라를 코어로 선택해 생명력 흡수와 공격력을 챙기세요. 신발은 마법 저항력을 높이고 침묵과 둔화 지속시간을 줄여 주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. (R)\'황천의 손아귀\' 제압은 정화로 풀 수 없으니 정화 대신 점화로 킬각을 만드는 것이 좋아요.' },
    '말파이트': { lv1: '말파이트는 (Q)\'지진의 파편\'으로 이동 속도를 훔치며 견제하는데, 대상 지정 스킬이라 미니언 뒤에 숨어도 맞으니 주의하세요. (P)\'화강암 방패\' 보호막이 있을 때는 평타 교환을 피하고, 보호막이 사라진 뒤 (Q)\'찌르기\'로 붙어서 짧게 딜교환을 해요. 초반에는 (P)\'치명적인 검무\' 급소를 쳐서 체력을 회복하며 버티세요.', lv3: '말파이트의 (E)\'지면 강타\'는 이동 불가 효과가 없어 (W)\'응수\'로 기절을 노리기 어려우니 공격 속도 감소 범위 밖에서 싸우세요. (W)\'천둥소리\'가 켜진 상태의 평타는 여진 피해를 입히니 (E)\'대가의 검술\'로 빠르게 두 번 때리고 빠지는 구도를 만드세요. (Q)\'지진의 파편\'의 둔화에 걸렸을 때 (Q)\'찌르기\'로 거리를 좁혀 급소를 가격하세요.', lv6: '(R)\'멈출 수 없는 힘\'은 저지 불가 돌진이라 도중에 멈출 수 없으며, 맞으면 공중에 떠서 아무것도 못 하니 (W)\'응수\'로 타이밍 맞춰 막아 기절시키세요. (R)\'대결투\'를 사용해 말파이트의 높은 체력을 고정 피해로 깎아내며 킬각을 보세요. 정글러가 올 때 (R)\'멈출 수 없는 힘\'에 맞으면 그대로 잡히니 항상 거리 조절에 신경 쓰세요.', item: '첫 코어는 굶주린 히드라로 가서 광역 피해와 흡혈로 라인 관리와 지속 교전을 함께 챙기세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 순간이동을 추천해요. 말파이트의 돌진을 피하거나 (R)\'대결투\' 각을 잡기 위해 점멸이 필요하며, 탑 라인 특성상 순간이동으로 합류하는 것이 중요해요.' },
    '모데카이저': { lv1: '모데카이저는 (Q)\'말살\'을 한 명에게 맞히면 피해가 커지고 (P)\'암흑 탄생\' 오라가 켜지면 위험해요. (P)\'암흑 탄생\'이 발동되기 전에 (Q)\'찌르기\'를 활용해 짧게 교환하고 거리를 조절하세요. 첫 웨이브를 받아먹으며 (P)\'치명적인 검무\'의 급소를 찌를 준비를 해야 해요.', lv3: '(E)\'죽음의 손아귀\'로 끌어당길 때 (W)\'응수\'를 사용해 이동 불가 효과를 막고 기절을 노리세요. (W)\'불멸\' 보호막이 켜진 상태에서는 억지로 싸우지 말고 보호막이 빠질 때까지 기다려야 해요. (E)\'대가의 검술\'로 둔화를 걸고 (P)\'치명적인 검무\'의 급소를 가격하며 딜교환을 하세요.', lv6: '모데카이저가 (R)\'죽음의 세계\'를 쓰면 능력치를 뺏기니 그 안에서 (P)\'치명적인 검무\'의 급소를 빠르게 가격해 체력을 회복하며 버텨야 해요. (R)\'죽음의 세계\' 안에서는 순간이동이나 다른 스킬로 탈출할 수 없으니 (W)\'응수\'를 아껴서 모데카이저의 공격을 막으세요. 모데카이저의 (E)\'죽음의 손아귀\'가 빠진 타이밍에 (R)\'대결투\'를 켜고 적극적으로 싸우세요.', item: '헤르메스의 발걸음을 먼저 가서 마법 저항력과 강인함을 챙기세요. 첫 코어 아이템으로는 생명력 흡수가 붙은 굶주린 히드라를 선택해 지속 싸움 능력을 높여요.', spell: '점멸과 점화를 추천해요. (W)\'불멸\'을 통해 체력을 회복하는 모데카이저의 회복량을 점화로 억제하며 킬각을 잡으세요.' },
    '문도박사': { lv1: '문도 박사는 (Q)\'오염된 뼈톱\'으로 현재 체력 비례 피해를 주고 둔화를 걸어요. 이 스킬은 처음 맞는 적에게만 적용되니 미니언 뒤에서 피하고 (Q)\'찌르기\'로 짧게 들어가 급소를 치세요. 너무 오래 붙어 있으면 체력 재생 때문에 이득을 보기 어려우니 짧은 딜교환을 반복하세요.', lv3: '(W)\'심장 전기 충격\'이 켜진 동안은 지속 피해를 입고 문도 박사가 체력을 회복하니 거리를 유지하세요. (E)\'대가의 검술\'을 사용해 빠르게 급소를 가격하고 (Q)\'찌르기\'로 빠져나오는 식으로 딜교환을 하세요. (W)\'응수\'는 문도 박사의 피해를 막는 용도로 쓰고, 상대의 (E)\'둔기에 의한 외상\' 강공격 타이밍을 피해 움직이세요.', lv6: '(R)\'대결투\'를 사용해 문도 박사의 높은 체력을 고정 피해로 빠르게 깎으세요. 문도 박사가 (R)\'최대 투여량\'을 쓰면 체력이 크게 회복되니 그 직후 점화를 걸어 회복량을 줄이세요. 라인을 밀어 넣고 (Q)\'찌르기\'와 (P)\'치명적인 검무\'로 급소를 빠르게 터뜨려 킬각을 잡으세요.', item: '몰락한 왕의 검을 첫 코어로 가고 처형인의 대검을 섞어 체력 비례 피해와 치유 감소를 챙기세요. 신발은 문도 박사의 (Q)\'오염된 뼈톱\'과 (W)\'심장 전기 충격\'의 마법 피해를 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 문도 박사는 (R)\'최대 투여량\'과 기본 체력 재생으로 회복량이 매우 많아 점화의 치유 감소가 필수적이에요.' },
    '바루스': { lv1: '바루스는 (Q)\'꿰뚫는 화살\'을 오래 조준할수록 피해가 커지니 조준하는 동안 옆으로 움직여 피하세요. (Q)\'꿰뚫는 화살\'은 적을 관통하니 미니언 뒤에 서도 막히지 않아요. (Q)\'찌르기\'로 빠르게 접근해 급소를 치고 빠지는 식으로 피해를 줄이세요.', lv3: '(E)\'퍼붓는 화살\'의 오염된 지면은 둔화를 걸고 회복을 줄이니 그 위에서 싸우지 마세요. (W)\'응수\'로 (E)\'퍼붓는 화살\'이나 (Q)\'꿰뚫는 화살\'을 막아내어 반격의 기회를 잡으세요. (Q)\'찌르기\'로 진입한 뒤 (E)\'대가의 검술\'로 빠르게 두 번 공격하고 급소를 가격해 체력을 회복하며 딜교환하세요.', lv6: '(R)\'부패의 사슬\'의 속박을 (W)\'응수\'로 막아내면 바루스를 기절시켜 쉽게 제압할 수 있어요. (R)\'부패의 사슬\'을 그대로 맞으면 이동이 차단되어 일방적으로 공격받으니 주의하세요. 바루스가 궁극기를 빗맞혔을 때 (R)\'대결투\'를 켜고 빠르게 파고들어 급소를 모두 가격하세요.', item: '판금 장화로 바루스의 기본 공격 피해를 줄이세요. 삼위일체를 첫 코어로 선택해 공격력과 체력을 높이고 주문 검 효과로 짧은 딜교환 효율을 높이세요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도로 바루스의 견제 거리를 뚫고 빠르게 접근할 수 있어요.' },
    '베인': { lv1: '베인은 (W)\'은화살\'로 최대 체력 비례 고정 피해를 입히며 (Q)\'구르기\'로 거리를 조절해요. 1~2레벨에는 무리하게 진입하기보다 미니언 뒤에서 대기하다가 베인이 막타를 치러 올 때 (Q)\'찌르기\'로 진입해 짧게 딜교환하세요. 베인의 평타 세 번이 다 들어가기 전에 빠르게 빠지는 것이 중요해요.', lv3: '베인의 (E)\'선고\'는 벽에 부딪히면 기절하므로 항상 벽에서 멀리 떨어져서 싸우세요. (E)\'선고\'를 (W)\'응수\'로 막아내면 베인을 기절시킬 수 있고, 이때 (E)\'대가의 검술\'을 사용해 빠르게 급소를 치며 몰아치세요. 베인이 (Q)\'구르기\'로 거리를 벌리기 전에 (Q)\'찌르기\'로 계속 따라붙어야 해요.', lv6: '베인이 (R)\'결전의 시간\'을 켜면 (Q)\'구르기\' 사용 시 투명 상태가 되어 접근이 매우 까다로워져요. (R)\'대결투\'를 사용해 급소를 빠르게 드러내고, 베인이 투명해지기 전이나 (E)\'선고\'를 뺀 타이밍에 진입해 고정 피해를 입히세요. 투명 상태일 때는 무리하게 쫓지 말고 정글러를 부르거나 라인을 당겨서 관리하세요.', item: '삼위일체로 공격력과 체력을 챙기고 적에게 빠르게 접근하세요. 신발은 베인의 기본 공격 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (W)\'응수\'로 기절시킨 짧은 순간에 점화와 함께 폭발적인 피해를 넣어 베인을 처치하세요.' },
    '볼리베어': { lv1: '볼리베어는 (Q)\'번개 강타\'로 이동 속도를 높여 빠르게 접근해 기절시키려 해요. (Q)\'찌르기\'를 이용해 거리 조절을 하며 급소를 쳐서 체력을 회복하고 빠르게 빠져나가세요. 초반 평타 교환은 볼리베어가 강하니 무리하게 붙지 말고 짧은 딜교환을 반복하세요.', lv3: '(Q)\'번개 강타\'의 기절을 (W)\'응수\'로 막아내면 역으로 기절시켜 큰 피해를 줄 수 있어요. 볼리베어가 (E)\'천공 분열\'을 사용해 보호막을 얻으려 할 때 범위 밖으로 (Q)\'찌르기\'를 써서 피하세요. (E)\'대가의 검술\'로 빠르게 급소를 치고, 표식이 남은 나에게 볼리베어가 (W)\'광란의 상처\'를 다시 써서 추가 피해와 회복을 얻기 전에 거리를 벌리세요.', lv6: '(R)\'폭풍을 부르는 자\'로 포탑을 끄고 다이브를 시도할 수 있으니 체력이 낮을 때는 포탑 안에서도 주의하세요. (R)\'대결투\'를 사용하여 빠르게 급소를 모두 가격해 최대 체력 비례 고정 피해를 입히고 치유 효과를 얻으세요. (R)\'폭풍을 부르는 자\' 착지 지점 근처에 있으면 내가 둔화되니 착지 범위를 피한 뒤 (Q)\'찌르기\'로 급소를 노리세요.', item: '삼위일체를 가서 공격력과 체력을 보강하고 지속 딜 능력을 높이세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 볼리베어가 (W)\'광란의 상처\'로 체력을 회복하는 것을 점화로 방해하며 킬각을 잡으세요.' },
    '블라디미르': { lv1: '블라디미르는 (Q)\'수혈\'로 체력을 흡수하며 견제해요. (Q)\'수혈\'은 대상 지정 스킬이라 미니언 뒤에 숨어도 피할 수 없으니 거리 조절에 신경 써야 해요. 1~2레벨에는 무리하게 딜교환하기보다 (P)\'치명적인 검무\'의 급소를 챙기며 버티세요.', lv3: '블라디미르가 (E)\'선혈의 파도\'를 쓸 때는 미니언 뒤에 숨어서 피해를 줄이세요. 블라디미르가 (W)\'피의 웅덩이\'를 사용해 공격을 피하려 하면 웅덩이가 끝나는 타이밍에 맞춰 (Q)\'찌르기\'로 접근하세요. (E)\'대가의 검술\'로 둔화를 걸며 붙으면 딜교환을 시도하세요.', lv6: '블라디미르가 (R)\'혈사병\'을 사용해 감염시키면 받는 피해가 커지니 조심해야 해요. (R)\'대결투\'로 급소를 노리되 블라디미르가 (W)\'피의 웅덩이\'로 타이밍을 뺏지 못하게 주의하세요. (W)\'피의 웅덩이\'가 빠진 뒤에는 블라디미르가 공격을 피할 수단이 없으니 그때 (Q)\'찌르기\'로 붙어 마무리하세요.', item: '몰락한 왕의 검을 먼저 올려서 생명력 흡수 효과를 활용하세요. 신발은 마법 저항력을 얻는 헤르메스의 발걸음을 추천해요. 블라디미르의 마법 피해에 대비하기 위해서예요.', spell: '점멸과 점화를 추천해요. 블라디미르는 (Q)\'수혈\'로 체력을 회복하니 점화로 회복 효과를 줄여야 해요.' },
    '뽀삐': { lv1: '뽀삐가 (Q)\'망치 강타\'로 둔화 지대를 만들며 견제하니 그 범위를 피해 움직이세요. (Q)\'찌르기\'로 급소를 찔러 체력을 회복하되 뽀삐가 (P)\'강철의 외교관\' 방패를 주워 보호막을 얻기 전에 짧게 교환하세요. 첫 웨이브에서는 무리하게 붙지 말고 거리 조절을 하며 급소를 하나씩 공략하세요.', lv3: '뽀삐가 (W)\'굳건한 태세\'를 켜면 (Q)\'찌르기\' 돌진이 막히고 둔화되니 이 스킬이 빠진 것을 확인하고 진입하세요. (E)\'용감한 돌진\'으로 벽에 밀어 기절시키려 할 때 (W)\'응수\'로 막아내어 역으로 기절시키면 교환을 앞서요. (E)\'대가의 검술\' 두 번의 공격을 빠르게 적중시켜 뽀삐의 체력을 깎고 빠르게 빠져나오세요.', lv6: '(R)\'대결투\'를 사용해 모든 급소를 빠르게 찌르되 (R)\'수호자의 심판\'에 맞아서 멀리 날아가지 않게 주의하세요. 뽀삐의 (W)\'굳건한 태세\'가 켜진 동안은 (Q)\'찌르기\'를 아끼고 일반 공격과 (E)\'대가의 검술\'로 급소를 공략하세요. 라인을 너무 밀면 (R)\'수호자의 심판\'으로 아군 포탑 쪽으로 날려 보낼 수 있으니 위치 선정에 유의하세요.', item: '삼위일체와 판금 장화를 추천해요. 삼위일체는 공격력과 체력을 모두 챙겨 지속 교전 능력을 높여주고, 판금 장화는 뽀삐의 기본 공격 피해를 줄여줘요.', spell: '점멸과 순간이동을 추천해요. (E)\'용감한 돌진\'의 벽 기절을 피하거나 (R)\'대결투\' 각을 잡기 위해 점멸이 필요하고, 탑 라인 유지력을 위해 순간이동을 사용하세요.' },
    '사이온': { lv1: '사이온은 (E)\'학살자의 포효\'를 미니언에 맞히면 뒤의 적까지 둔화시키고 방어력을 낮추니 일직선으로 서지 마세요. 사이온이 (Q)\'대량 학살 강타\'를 충전할 때는 옆으로 비켜서서 피해를 피하며 (Q)\'찌르기\'로 짧게 딜교하세요.', lv3: '사이온의 (W)\'영혼의 용광로\' 보호막이 켜져 있을 때는 딜을 쏟지 말고 보호막이 끝난 뒤에 (E)\'대가의 검술\'과 함께 공격하세요. 사이온이 (Q)\'대량 학살 강타\'로 공중으로 띄우려 할 때 (W)\'응수\'를 사용하여 기절을 노리는 것이 중요해요.', lv6: '사이온이 (R)\'멈출 수 없는 맹공\'으로 돌진하면 옆으로 비켜서서 충돌을 피하고 (R)\'대결투\'를 사용하여 급소를 빠르게 공략하세요. 사이온이 처치되어도 (P)\'영광스러운 죽음\'으로 잠시 되살아나니 (R)\'대결투\'의 치유 효과를 활용하며 전투를 이어가세요.', item: '첫 코어는 굶주린 히드라로 가서 광역 피해와 흡혈로 라인 관리와 지속 교전을 함께 챙기세요. 공격 속도를 높여 급소를 빠르게 타격할 수 있도록 광전사의 군화를 추천해요.', spell: '점멸과 점화를 추천해요. 사이온의 체력이 높으니 점화로 마무리 피해를 입히고 체력 회복 효과를 감소시키세요.' },
    '사일러스': { lv1: '사일러스는 (Q)\'사슬 후려치기\'로 견제하며 (P)\'페트리사이트 폭발\'이 충전되면 평타에 추가 피해를 입히니 주의하세요. 1~2레벨에는 사슬이 교차하는 지점을 피하며 (Q)\'찌르기\'로 거리를 조절하세요. 사일러스가 스킬을 쓴 직후에는 충전된 평타가 오니 거리를 두고, 충전이 없는 틈에 (P)\'치명적인 검무\'의 급소를 노려 맞대응하세요.', lv3: '사일러스가 (E)\'도주 / 억압\'을 재사용하여 공중으로 띄우려 할 때 (W)\'응수\'를 사용하여 기절을 시키세요. 사일러스가 (W)\'국왕시해자\'를 사용하여 체력을 회복하며 돌진할 때는 (E)\'대가의 검술\'로 빠르게 딜교환을 하세요. (Q)\'사슬 후려치기\'의 둔화 효과에 계속 걸리지 않도록 (Q)\'찌르기\'를 적절히 사용하세요.', lv6: '사일러스가 (R)\'강탈\'로 (R)\'대결투\'를 훔쳐 사용하면 피오라와 비슷한 방식으로 급소를 노리니 조심하세요. 사일러스의 (W)\'국왕시해자\' 회복이 빠진 것을 확인한 뒤 (R)\'대결투\'를 켜고 급소를 모두 가격하세요. 사일러스가 (E)\'도주 / 억압\'으로 들어올 때 (W)\'응수\'로 끊어주는 것이 중요해요.', item: '첫 코어 아이템으로 굶주린 히드라를 선택하여 생명력 흡수와 전투 지속력을 챙기세요. 신발은 사일러스의 마법 피해를 줄여주는 헤르메스의 발걸음을 신으세요.', spell: '점멸과 점화를 추천해요. 사일러스가 (W)\'국왕시해자\'로 체력을 회복하는 것을 점화로 억제하세요.' },
    '세주아니': { lv1: '1~2레벨에는 (Q)\'찌르기\'를 활용해 급소를 찌르며 체력을 회복하세요. 세주아니가 (Q)\'혹한의 맹습\'으로 진입하며 공중으로 띄우려 할 때 거리 조절에 신경 써야 해요. 무리하게 붙기보다 짧은 딜교환을 반복하며 상대의 체력을 깎으세요.', lv3: '(E)\'대가의 검술\'을 사용해 빠르게 급소를 치고 빠지는 딜교환을 하세요. 세주아니가 (W)\'혹한의 서릿발\'로 중첩을 쌓고 (E)\'만년 서리\'로 기절시키려 할 때 (W)\'응수\'로 이를 막아내면 상대를 기절시킬 수 있어요. 상대의 (Q)\'혹한의 맹습\' 돌진 타이밍에 맞춰 (W)\'응수\'를 쓰면 역공 기회를 잡기 좋아요.', lv6: '(R)\'대결투\'를 사용해 세주아니의 높은 체력을 고정 피해로 빠르게 깎아내세요. 세주아니가 (R)\'빙하 감옥\' 올가미를 던져 기절시키려 할 때 (W)\'응수\'로 막아내면 킬각을 잡기 편해요. 라인을 적절히 밀어 정글 개입을 어렵게 만들고, 좁은 길목에서의 교전을 피하세요.', item: '헤르메스의 발걸음과 삼위일체를 추천해요. 강인함으로 (E)\'만년 서리\' 같은 군중 제어 지속시간을 줄이고, 체력과 공격력을 얻어 지속 싸움을 이끌어내기 위해서예요.', spell: '점멸과 순간이동을 추천해요. (R)\'대결투\'와 함께 순간적으로 거리를 좁혀 급소를 찌르고, 라인 복귀와 합류를 빠르게 하기 위해서예요.' },
    '세트': { lv1: '세트는 (Q)\'주먹다짐\'을 활용한 맞딜이 매우 강력하니 1~2레벨에는 무리하게 평타 싸움을 하지 마세요. (Q)\'찌르기\'로 세트의 체력을 깎으며 거리를 조절하고 (P)\'치명적인 검무\'의 급소를 챙기며 성장하세요. 세트가 (Q)\'주먹다짐\'을 켜고 다가오면 뒤로 물러나 피해를 최소화해야 해요.', lv3: '세트가 (E)\'안면 강타\'로 끌어당기려 할 때 (W)\'응수\'를 사용하여 기절을 유도하는 것이 핵심이에요. 세트의 (W)\'강펀치\'는 투지에 따라 큰 고정 피해를 주니 (W)\'응수\'로 피해를 막거나 (E)\'대가의 검술\'의 둔화로 거리를 조절하세요. 세트의 스킬이 빠진 타이밍에 (Q)\'찌르기\'와 (E)\'대가의 검술\'을 연계해 급소를 공략하세요.', lv6: '세트가 (R)\'대미 장식\'으로 나를 붙잡아 제압한 뒤 내리꽂으면 매우 위험하니 붙잡히지 않게 거리 조절에 신경 쓰세요. 세트의 (W)\'강펀치\' 보호막이 사라진 시점에 (R)\'대결투\'를 사용하여 급소를 빠르게 가격하세요. 세트가 궁극기를 사용한 직후에는 다시 붙기보다 라인을 관리하며 정글러의 위치를 확인하세요.', item: '첫 코어 아이템으로 굶주린 히드라를 구매해 전투 지속력을 높이세요. 신발은 세트의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 세트의 (P)\'투기장의 투지\'를 통한 체력 회복 효과를 줄이세요.' },
    '쉔': { lv1: '쉔은 (Q)\'황혼 강습\'으로 최대 체력 비례 피해를 주고 (P)\'기 보호막\'을 얻으니 무리하게 맞붙지 마세요. (Q)\'찌르기\'로 거리 조절을 하며 급소를 노려 체력을 회복하고, 쉔의 검이 지나가는 경로를 피하며 대응하세요. 1~2레벨에는 쉔이 스킬을 쓰기 전에 먼저 (Q)\'찌르기\'로 딜교환을 시도하는 것이 좋아요.', lv3: '쉔이 (E)\'그림자 돌진\'으로 들어오며 도발을 걸려고 하면 (W)\'응수\'로 쉔의 공격을 막아내세요. (W)\'의지의 결계\' 안의 아군은 기본 공격이 차단되므로 결계가 사라질 때까지 기다렸다가 (E)\'대가의 검술\'로 진입하세요. (Q)\'황혼 강습\'의 둔화가 끝나면 (Q)\'찌르기\'로 다시 진입해 급소를 공략하세요.', lv6: '쉔이 (R)\'단결된 의지\'를 사용해 다른 곳으로 이동하면 빠르게 라인을 밀어 압박하세요. (R)\'대결투\'를 통해 급소를 모두 가격하면 강력한 피해를 줄 수 있으니 (W)\'응수\'로 상대의 돌진을 잘 받아내야 해요. (R)\'단결된 의지\'가 빠진 상황에서 (Q)\'찌르기\'로 진입해 킬각을 잡으세요.', item: '첫 코어로 삼위일체를 선택해 전투 지속력을 높이세요. 신발은 쉔의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. (R)\'대결투\'를 사용한 뒤 쉔의 체력이 낮아졌을 때 점화를 사용해 마무리하세요.' },
    '쉬바나': { lv1: '(Q)\'찌르기\'로 급소를 빠르게 찌르고 빠지는 식으로 견제하세요. 상대의 (E)\'용암 분출\' 범위 밖에서 움직이며 체력을 깎는 것이 중요해요. 첫 웨이브에서는 무리하게 진입하지 말고 거리 조절에 집중하세요.', lv3: '(W)\'지옥불 방패\'의 보호막이 사라진 타이밍에 (E)\'대가의 검술\'로 빠르게 딜교환을 하세요. 상대가 (E)\'용암 분출\'을 사용할 때 (W)\'응수\'로 둔화를 막아내면 흐름을 가져올 수 있어요. (Q)\'찌르기\'로 급소를 찌르며 상대의 스킬 쿨타임을 계속 확인하세요.', lv6: '(R)\'용의 강림\'으로 변신한 상대는 체력이 많아지니 (R)\'대결투\'를 사용해 최대 체력 비례 고정 피해를 입히세요. 상대가 변신하며 돌진할 때 (W)\'응수\'로 대응해 기절시키면 킬각을 잡기 편해요. 라인을 밀어넣고 정글러의 개입을 유도하며 압박하세요.', item: '헤르메스의 발걸음과 삼위일체를 추천해요. 마법 저항력으로 (E)\'용암 분출\' 피해를 줄이고 공격 속도와 체력으로 지속 교전 능력을 높이기 위해서예요.', spell: '점멸과 순간이동을 추천해요. 순간이동을 통해 라인 복귀와 합류를 빠르게 하고 점멸로 변수를 만들어야 해요.' },
    '스웨인': { lv1: '스웨인은 (Q)\'죽음의 손길\'로 견제하고 (P)\'굶주린 새떼\'로 체력을 회복하며 버텨요. (Q)\'찌르기\'로 빠르게 접근해 급소를 가격하고 짧은 딜교환 후 뒤로 빠지세요. 초반에 체력 차이를 벌려두지 않으면 상대의 최대 체력이 계속 늘어나서 힘들어요.', lv3: '스웨인이 (E)\'속박명령\'을 사용할 때 (W)\'응수\'로 막아내면 상대를 기절시키고 확실한 딜교환 기회를 잡을 수 있어요. (E)\'속박명령\' 파동이 돌아올 때 속박되는 타이밍에 맞춰 (W)\'응수\'를 쓰세요. 기절시킨 후 (E)\'대가의 검술\'로 빠르게 급소를 타격해 체력을 회복하세요.', lv6: '스웨인이 (R)\'악의 승천\'을 켜고 주변 생명력을 흡수할 때는 (R)\'대결투\'를 사용해 빠르게 급소를 모두 가격하세요. (R)\'악의 승천\'의 둔화 효과를 (W)\'응수\'로 막아내며 빠르게 치고 빠지는 것이 중요해요. 정글러가 올 때 (E)\'속박명령\'을 (W)\'응수\'로 반격하면 한 번에 처치하기 편해요.', item: '마법 피해를 줄이고 (E)\'속박명령\'의 속박 시간을 줄여주는 헤르메스의 발걸음을 신으세요. 첫 코어로는 공격력과 체력을 모두 챙겨 지속 싸움이 가능한 갈라진 하늘을 추천해요.', spell: '점멸과 점화를 추천해요. 스웨인은 (P)\'굶주린 새떼\'와 (R)\'악의 승천\'으로 체력을 많이 회복하므로 점화로 이를 억제해야 해요.' },
    '스카너': { lv1: '스카너가 (Q)\'부서진 대지/지반 돌출\'로 강화된 기본 공격을 사용하며 견제할 때 거리를 조절하세요. 해당 투사체를 피하며 (P)\'치명적인 검무\'의 급소를 노리는 것이 좋아요. 초반에는 무리한 교전보다는 파밍에 집중하며 안정적으로 성장하세요.', lv3: '스카너가 (E)\'이쉬탈의 격돌\'로 돌진할 때 (W)\'응수\'를 사용하여 기절을 유도해 보세요. 스카너가 (W)\'대지의 수호자\'로 보호막을 얻었을 때는 (E)\'대가의 검술\'로 무리하게 들어가기보다 기회를 기다려요. (Q)\'찌르기\'를 사용하여 스카너의 (P)\'진동의 가닥\' 중첩이 쌓이기 전에 딜교환을 하세요.', lv6: '스카너가 (R)\'꿰뚫기\'를 사용하면 제압 상태가 되어 스킬을 쓸 수 없으니 주의하세요. (R)\'대결투\'를 사용하여 급소를 빠르게 가격하며 스카너의 스킬 쿨타임을 활용해 전투를 이끌어 가세요. 라인을 너무 깊게 밀면 상대 정글러의 개입을 받을 수 있으니 조심하세요.', item: '첫 코어 아이템으로는 굶주린 히드라를 선택하여 생명력 흡수와 라인 클리어를 챙기세요. 신발은 헤르메스의 발걸음을 구매하여 스카너의 (E)\'이쉬탈의 격돌\' 기절과 둔화 지속시간을 줄여보세요.', spell: '점멸과 점화를 추천해요. (R)\'꿰뚫기\'에 제압당하기 전에 점멸로 거리를 조절하고, 점화로 마무리 피해를 넣으세요.' },
    '신지드': { lv1: '신지드가 (Q)\'맹독의 자취\'를 남기며 지나갈 때 독구름 속에 서 있지 않도록 주의하세요. (Q)\'찌르기\'로 신지드의 급소를 맞히며 체력을 회복하고 거리를 조절하며 버텨야 해요. 미니언 사이에서 독구름 피해를 최소화하며 라인을 관리하세요.', lv3: '신지드가 (W)\'초강력 접착제\'를 사용하면 이동 스킬을 쓸 수 없으니 주의하세요. 신지드의 (E)\'던져넘기기\'를 (W)\'응수\'로 막아내서 기절을 시키는 것이 핵심이에요. 기절시킨 직후에 (E)\'대가의 검술\'을 사용하여 빠르게 딜교환을 하세요.', lv6: '신지드가 (R)\'광기의 물약\'을 사용하면 지속적인 피해가 강해지니 정면 대결은 피하세요. (R)\'대결투\'를 켜고 급소를 빠르게 공략하며 (W)\'응수\'로 신지드의 기술을 끊어주는 것이 중요해요. 신지드가 라인을 밀고 도망가면 정글러를 불러 함께 압박하세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 전투 지속력을 높이세요. 신발은 신지드의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도로 신지드의 (Q)\'맹독의 자취\'를 빠르게 벗어나며 추격하세요.' },
    '신짜오': { lv1: '1~2레벨에는 (Q)\'삼조격\' 세 번째 공격의 공중으로 띄우기 효과를 조심하며 짧게 딜교환해요. (Q)\'찌르기\'로 급소를 찌르고 빠르게 빠지는 식으로 체력을 깎으세요. 상대의 기본 공격 횟수를 세며 무리한 진입을 피하세요.', lv3: '신 짜오가 (W)\'풍전참뢰\'나 (E)\'무쌍돌격\'으로 들어올 때 (W)\'응수\'로 공격을 막아내세요. 막은 직후 (E)\'대가의 검술\'로 빠르게 두 번 공격해 급소를 가격하세요. (Q)\'삼조격\'의 세 번째 공격이 공중으로 띄우니 그 타이밍에 (W)\'응수\'를 맞춰 쓰는 것이 핵심이에요.', lv6: '(R)\'대결투\'를 사용해 급소를 빠르게 공략하며 체력 비례 고정 피해를 입히세요. 상대가 (R)\'현월수호\'로 밀쳐내려 할 때 거리 조절에 유의하며 끈질기게 붙어 싸우세요. 정글러 개입이 심한 구간이니 라인을 적절히 밀고 뒤로 물러나세요.', item: '판금 장화와 삼위일체를 추천해요. 판금 장화는 신 짜오의 기본 공격 피해를 줄여주고 삼위일체는 공격력과 체력을 높여 지속 싸움에 도움을 줘요.', spell: '점멸과 순간이동을 추천해요. 순간이동으로 라인 복귀와 운영을 챙기고 점멸로 (W)\'응수\'의 변수를 만들거나 생존하세요.' },
    '아이번': { lv1: '아이번의 원거리 공격과 (Q)\'덩굴뿌리\' 견제를 조심하며 미니언 뒤에서 버티세요. (Q)\'찌르기\'로 거리를 좁히며 급소를 가격해 체력을 회복하는 것이 중요해요. 무리하게 진입하기보다 경험치를 챙기며 기회를 보세요.', lv3: '아이번의 (Q)\'덩굴뿌리\'를 (W)\'응수\'로 막아내어 기절시킨 뒤 강력하게 공격하세요. 기절한 적에게 (E)\'대가의 검술\'을 사용하여 빠르게 급소를 타격하고 피해를 입히세요. (E)\'보호의 씨앗\' 폭발로 인한 둔화에 걸리지 않도록 주의하세요.', lv6: '(R)\'대결투\'를 사용하여 아이번의 급소를 빠르게 타격하고 체력을 회복하세요. (R)\'데이지!\'의 연속 공격으로 공중으로 띄워지는 것을 주의하며 빠르게 움직이세요. (W)\'수풀 가꾸기\'로 적의 시야가 가려질 수 있으니 정글 개입을 항상 경계하세요.', item: '헤르메스의 발걸음과 삼위일체를 가세요. 헤르메스의 발걸음은 마법 저항력과 강인함을 제공해 속박 시간을 줄여줘요. 삼위일체는 공격력과 체력 그리고 공격 속도를 올려줘요.', spell: '점멸과 순간이동을 추천해요. 점멸로 (W)\'응수\'의 사거리를 보완하거나 빠르게 진입하고 순간이동으로 라인 복귀와 운영을 하세요.' },
    '아지르': { lv1: '아지르가 (W)\'일어나라!\'와 (Q)\'사막의 맹습\'으로 견제할 때 체력 관리에 유의해요. (Q)\'사막의 맹습\'은 미니언을 통과하므로 거리 조절에 신경 쓰고 (Q)\'찌르기\'로 접근해 (P)\'치명적인 검무\'의 급소를 가격하세요.', lv3: '(E)\'대가의 검술\'로 적을 둔화시키고 강한 피해를 입히며 압박을 이어가세요. 아지르가 (E)\'신기루\'를 사용해 거리를 벌리려 하면 (Q)\'찌르기\'로 끝까지 추격하고 (W)\'응수\'로 상대의 공격을 막아내세요.', lv6: '(R)\'대결투\'를 사용하여 급소를 빠르게 공격하며 강하게 몰아붙이세요. 아지르가 (R)\'황제의 진영\'으로 밀어내려 할 때 (W)\'응수\'로 막아내면 상대를 기절시켜 확실한 킬각을 잡을 수 있어요.', item: '헤르메스의 발걸음과 삼위일체를 가요. 마법 저항력과 강인함을 주는 헤르메스의 발걸음으로 버티고, 삼위일체로 공격력과 체력을 보강해요.', spell: '점멸과 순간이동을 추천해요. 점멸로 아지르의 사거리를 뚫고 빠르게 진입하며 순간이동으로 라인 복귀를 빠르게 하기 위해서예요.' },
    '아칼리': { lv1: '아칼리가 (Q)\'오연투척검\'으로 견제하며 (P)\'암살자의 표식\' 원을 이용해 평타 사거리를 늘리려 해요. 무리하게 진입하기보다 (Q)\'찌르기\'로 미니언과 급소를 함께 쳐서 체력을 관리하세요. 초반에는 아칼리의 기력이 빠질 때까지 기다렸다가 짧게 딜교환을 하세요.', lv3: '아칼리가 (E)\'표창곡예\'로 들어올 때 (W)\'응수\'로 막아내면 둔화시켜 역공할 수 있어요. (W)\'황혼의 장막\' 안에서는 아칼리가 투명 상태라 위치를 알기 어려우니 연막이 사라지거나 아칼리가 공격해 모습이 드러날 때 (Q)\'찌르기\'로 붙으세요. (E)\'대가의 검술\'로 빠르게 급소를 가격해 체력을 회복하며 압박하세요.', lv6: '(R)\'무결처형\'의 두 번째 돌진 경로를 예측해 피하고 (R)\'대결투\'로 급소를 모두 터뜨려 고정 피해를 입히세요. 아칼리가 연막으로 숨어 (R)\'무결처형\' 각을 볼 때 (W)\'응수\'를 켜서 진입을 둔화시키면 좋아요. 라인을 밀어넣고 포탑 근처에서 싸우면 아칼리가 도망갈 곳이 없어 킬각을 잡기 편해요.', item: '첫 귀환에 주문포식자를 먼저 사서 아칼리의 마법 폭딜을 막아 내고, 첫 코어는 굶주린 히드라로 가세요. 신발은 아칼리의 군중 제어 시간을 줄여 주는 헤르메스의 발걸음을 맞추세요.', spell: '점멸과 점화를 추천해요. 점화의 강력한 지속 피해를 더해 낮은 체력의 아칼리를 확실하게 마무리하세요.' },
    '아크샨': { lv1: '(Q)\'복수의 부메랑\'을 이용한 견제를 버티며 적절한 거리 조절을 해요. (Q)\'찌르기\'로 무리하게 진입하기보다는 급소가 생길 때까지 기다리며 경험치를 최대한 챙기세요.', lv3: '아크샨이 (E)\'영웅의 비상\'으로 매달려 이동하며 사격할 때 (W)\'응수\'로 탄환 피해를 막아내세요. (E)\'대가의 검술\'을 사용해 빠르게 급소를 가격하고 (Q)\'찌르기\'로 추격하며 딜교환을 마무리하세요.', lv6: '(R)\'대결투\'로 급소를 빠르게 터뜨려 체력 회복과 피해량을 높이며 압박하세요. 상대가 (R)\'인과응보\'를 모으는 동안 빠르게 진입하거나 거리를 벌려 피해를 최소화해야 해요.', item: '판금 장화와 삼위일체를 추천해요. 판금 장화로 기본 공격 피해를 줄이고 삼위일체로 공격력과 체력을 높여 지속 전투력을 올리세요.', spell: '점멸과 순간이동을 추천해요. 원거리 챔피언의 견제로 인해 손실되는 라인 경험치와 체력을 관리하며 운영하는 것이 중요해요.' },
    '아트록스': { lv1: '아트록스는 (Q)\'다르킨의 검\'을 세 번 휘두르며 끝부분에 맞으면 공중으로 띄워지니 거리 조절에 신경 쓰세요. (P)\'사신 태세\'가 활성화된 기본 공격은 체력을 회복하니 무리하게 평타를 교환하지 마세요. 상대의 스킬이 빠진 틈을 타 (Q)\'찌르기\'로 급소를 가격하며 짧게 딜교환하세요.', lv3: '(W)\'지옥사슬\'에 맞으면 중앙으로 끌려가 다시 피해를 입으니 범위 밖으로 빠르게 벗어나세요. (Q)\'다르킨의 검\'의 띄우기 효과를 (W)\'응수\'로 막아내면 상대를 기절시킬 수 있어 매우 효과적이에요. 기절시킨 뒤 (E)\'대가의 검술\'로 빠르게 급소를 쳐서 피해를 입히고 빠지세요.', lv6: '(R)\'세계의 종결자\'를 켠 아트록스는 공격력과 회복량이 대폭 증가하니 궁극기 지속 시간 동안은 정면 승부를 피하세요. 상대의 궁극기가 끝날 때쯤 (R)\'대결투\'를 사용하여 급소를 모두 가격하고 고정 피해를 입히세요. 라인을 당겨 정글러를 부르고 (Q)\'찌르기\'로 빠르게 진입해 킬각을 잡으세요.', item: '첫 코어는 굶주린 히드라로 가서 광역 피해와 흡혈로 라인 관리와 지속 교전을 함께 챙기세요. 신발은 아트록스의 기본 공격 피해를 줄여 주는 판금 장화를 맞추세요.', spell: '점멸과 점화를 추천해요. (P)\'사신 태세\'와 (E)\'파멸의 돌진\'으로 회복하는 아트록스의 체력 회복 효과를 점화로 억제해야 해요.' },
    '암베사': { lv1: '암베사는 (P)\'용사냥개의 발걸음\'으로 스킬 사용 후 짧게 돌진하며 평타를 강화하니 붙어서 싸울 때 주의하세요. (Q)\'교활한 휩쓸기\'의 외곽 피해를 피하며 (Q)\'찌르기\'로 급소를 찌르고 빠르게 빠지는 식으로 체력을 깎으세요. 암베사가 돌진 평타를 쓰기 전에 먼저 (Q)\'찌르기\'로 거리를 좁히거나 뒤로 빠져서 헛스윙을 유도하세요.', lv3: '(W)\'배척\'은 보호막을 얻고 준비하는 동안 챔피언에게 피해를 받으면 내려찍는 피해가 커지니, 암베사가 (W)\'배척\'을 쓰면 잠시 공격을 멈추세요. (E)\'찢어 가르기\'의 둔화 효과를 (W)\'응수\'로 막아내며 상대의 진입 흐름을 끊고 역으로 딜교환을 하세요. (E)\'대가의 검술\'을 사용해 빠르게 급소를 타격하고 (Q)\'찌르기\'로 마무리하며 암베사의 기력을 소모시키세요.', lv6: '(R)\'공개 처형\'은 멀리 있는 적을 제압하므로, 암베사와 적절한 거리를 유지하며 (W)\'응수\'로 제압 효과를 막아 기절시키세요. (R)\'대결투\'를 사용해 급소를 빠르게 드러내고 (Q)\'찌르기\'와 (E)\'대가의 검술\'을 섞어 고정 피해를 입히며 킬각을 잡으세요. 제압에 걸리면 아무것도 할 수 없으니, 암베사가 궁극기를 쓰기 전에 미리 거리를 벌리거나 (W)\'응수\' 준비를 하세요.', item: '첫 코어는 굶주린 히드라로 가서 광역 피해와 흡혈로 라인 관리와 지속 교전을 함께 챙기세요. 신발은 암베사의 강화 평타 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 암베사는 (R)\'공개 처형\'의 기본 지속 효과로 스킬 피해만큼 체력을 회복하니 점화로 회복을 줄이면서 확실하게 처치하세요.' },
    '애니비아': { lv1: '애니비아는 (Q)\'냉기 폭발\'로 견제하고 끝에서 터뜨려 기절시키니 구체가 멈추는 지점을 피해 옆으로 움직이세요. 구체를 피한 뒤 (Q)\'찌르기\'로 빠르게 접근해 급소를 타격하며 체력을 회복하세요. 미니언 뒤에 숨기보다 거리 조절을 통해 구체를 피하는 것이 중요해요.', lv3: '(W)\'결정화\' 벽이 세워지면 경로가 막히니 벽이 사라진 뒤에 (Q)\'찌르기\'로 진입하세요. (Q)\'냉기 폭발\'의 기절을 (W)\'응수\'로 막아내면 애니비아를 역으로 기절시켜 확실한 딜교환 기회를 잡을 수 있어요. (E)\'대가의 검술\'을 사용해 빠르게 급소를 치고 (E)\'동상\'의 추가 피해를 입기 전에 거리를 벌리세요.', lv6: '(R)\'얼음 폭풍\'의 둔화 때문에 접근이 어려우니 (Q)\'냉기 폭발\'의 기절을 (W)\'응수\'로 막아 역으로 기절시킨 뒤 (R)\'대결투\'를 사용해 빠르게 급소를 타격하세요. 애니비아가 (P)\'환생\'으로 알이 되었을 때 빠르게 공격해 부수지 않으면 체력을 모두 회복하고 다시 살아나요. 라인을 밀어두고 (R)\'얼음 폭풍\' 장판 밖에서 정글러와 함께 애니비아를 압박하세요.', item: '맬모셔스의 아귀를 첫 코어로 가서 마법 저항력을 챙기고 생명선 보호막으로 생존력을 높이세요. 신발은 (Q)\'냉기 폭발\'의 기절과 (R)\'얼음 폭풍\'의 둔화 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점멸로 (W)\'결정화\' 벽을 넘거나 급소 접근을 빠르게 하고, 점화로 마무리 피해를 입히세요.' },
    '야스오': { lv1: '야스오는 (Q)\'강철 폭풍\'으로 거리를 두며 견제하려 하니 (Q)\'찌르기\'로 짧게 치고 빠지며 대응하세요. (P)\'낭인의 길\' 보호막이 있는 동안은 무리하게 딜교환을 하지 말고 보호막이 사라진 시점에 (P)\'치명적인 검무\'의 급소를 노리세요.', lv3: '야스오가 (E)\'질풍검\'으로 미니언을 타고 들어오며 (Q)\'강철 폭풍\'의 회오리바람을 준비할 때 (W)\'응수\'로 에어본을 막아내세요. (W)\'바람 장막\'은 투사체만 막으니 돌진하는 (Q)\'찌르기\'는 그대로 쓸 수 있어요. 야스오의 스킬이 빠진 뒤에 (E)\'대가의 검술\'을 활용해 교환하세요.', lv6: '야스오의 (R)\'최후의 숨결\'은 공중에 뜬 적에게만 쓸 수 있으니, (Q)\'강철 폭풍\' 회오리바람이 날아올 때 미리 (W)\'응수\'로 막아 띄워지지 않게 하세요. (R)\'대결투\'를 사용해 급소를 모두 가격하면 체력을 회복하며 압박할 수 있으니 정글러가 올 때를 대비해 라인 관리에도 신경 쓰세요.', item: '몰락한 왕의 검을 구매하여 생명력 흡수로 싸움을 이어가세요. 신발은 야스오의 기본 공격 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 야스오의 (P)\'낭인의 길\' 보호막이 깨진 직후 점화로 마무리 피해를 입히기 좋아요.' },
    '오공': { lv1: '오공은 (Q)\'파쇄격\'으로 평타 사거리를 늘려 방어력을 깎으며 (P)\'바위 피부\'로 점점 단단해져요. 1~2레벨에는 (Q)\'찌르기\'로 급소를 빠르게 찌르고 빠지는 짧은 교환을 하세요. 무리하게 붙어 싸우면 오공의 방어력이 높아져서 피해를 주기 어려워요.', lv3: '오공이 (E)\'근두운 급습\'으로 돌격할 때 (W)\'응수\'를 사용하여 공격을 막고 둔화를 거세요. (W)\'분신 전사\'로 투명해지면 진짜 오공이 나타날 때까지 거리를 유지하며 기다려요. (E)\'대가의 검술\'을 사용해 빠르게 급소를 가격한 뒤 (Q)\'찌르기\'로 추격하며 딜교환을 마무리하세요.', lv6: '오공이 (R)\'회전격\'으로 공중에 띄우려 할 때 (W)\'응수\'로 막아내면 상대를 기절시키고 역공할 수 있어요. (R)\'대결투\'를 켜고 급소를 모두 가격해 고정 피해를 입히며 전투를 이끄세요. (R)\'회전격\'을 쓴 직후 오공이 빠져나가려 하면 (Q)\'찌르기\'로 끝까지 쫓아가며 마무리하세요.', item: '삼위일체를 첫 코어로 선택해 공격력과 체력 그리고 스킬 가속을 챙겨 지속 전투력을 높이세요. 신발은 오공의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 오공은 (P)\'바위 피부\'로 버티며 싸우니 점화의 추가 피해로 체력을 빠르게 깎아 마무리하세요.' },
    '오로라': { lv1: '오로라의 (Q)\'이중 저주\'가 날아오는 방향을 보고 옆으로 움직여서 피해를 줄이세요. (Q)\'찌르기\'로 미니언과 함께 오로라의 체력을 깎으며 (P)\'치명적인 검무\'의 급소를 노릴 준비를 하세요.', lv3: '오로라가 (E)\'마법의 문\'으로 둔화를 걸고 뒤로 도약하면 (Q)\'찌르기\'로 거리를 좁히세요. 오로라에게는 이동 불가 효과가 없어 (W)\'응수\'는 기절보다 공격을 막는 용도로 쓰세요. (E)\'대가의 검술\'을 활용해 오로라의 도약 이후 거리를 좁히며 급소를 타격하세요.', lv6: '오로라가 (R)\'세계의 경계\'를 사용해 영역을 만들면 영역 안에서 무리하게 싸우기보다 (R)\'대결투\'를 켜고 급소를 찾아 움직이세요. (W)\'장막 너머로\'로 투명해진 오로라를 조심하며 (W)\'응수\'를 아껴두었다가 오로라의 진입을 끊어내세요.', item: '첫 코어로 굶주린 히드라를 가서 라인 관리와 전투 지속력을 높이세요. 신발은 오로라의 마법 피해와 군중 제어 효과를 줄여주는 헤르메스의 발걸음을 신으세요.', spell: '점멸과 점화를 추천해요. 오로라가 (P)\'영혼 방호술\'로 체력을 회복하며 버티는 것을 점화로 방해하세요.' },
    '오른': { lv1: '오른은 (P)\'간이 대장간\' 덕분에 초반 방어력과 마법 저항력이 매우 높아요. (Q)\'용암 균열\'로 생성되는 용암 기둥 위치를 확인하며 둔화를 피하고 (Q)\'찌르기\'로 짧게 딜교환을 하세요.', lv3: '(E)\'화염 돌진\'이 지형에 부딪혀 에어본이 발생할 때 (W)\'응수\'를 사용해 이를 막아내고 기절시키세요. (W)\'불꽃 풀무질\'에 맞아 불안정 상태가 되면 기본 공격에 밀려날 수 있으니 주의하며 (E)\'대가의 검술\'로 급소를 공략하세요.', lv6: '(R)\'대장장이 신의 부름\'의 정령 방향을 잘 보고 (W)\'응수\'로 에어본을 막아내며 (R)\'대결투\'를 시작하세요. (R)\'대결투\'는 고정 피해를 입히니 오른의 스킬을 피하며 급소를 빠르게 가격해 킬각을 잡으세요.', item: '첫 코어로 몰락한 왕의 검을 가서 전투를 오래 이어가세요. 신발은 오른의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 오른은 방어력이 높으니 점화로 부족한 피해를 보충해 킬각을 보세요.' },
    '올라프': { lv1: '올라프는 (Q)\'역류\'를 던져 방어력과 이동 속도를 깎으며 압박해요. (Q)\'찌르기\'로 급소를 공략하며 짧게 딜교환을 하고 거리를 유지하세요. 올라프가 도끼를 주우러 가는 동선을 파악해 피해를 최소화해야 해요.', lv3: '올라프가 (W)\'버티기\'를 사용하면 보호막과 공격 속도가 올라가니 그 순간에는 무리하게 싸우지 마세요. (E)\'무모한 강타\'에는 이동 불가 효과가 없어 (W)\'응수\'로 기절을 노리기 어려우니 올라프의 공격을 막아내는 용도로 쓰세요. (E)\'대가의 검술\'로 둔화를 걸며 급소를 찾아 때리세요.', lv6: '올라프가 (R)\'라그나로크\'를 사용하면 이동 방해 효과에 면역이 되므로 (W)\'응수\'로 기절시키려 해도 소용없어요. 궁극기 사용 여부를 확인하고 (R)\'대결투\'를 활용해 급소를 빠르게 타격하며 전투를 이어가세요. 정글러가 개입할 때 올라프가 궁극기로 무시하고 달려들 수 있으니 주의해야 해요.', item: '첫 코어는 굶주린 히드라로 가서 광역 피해와 흡혈로 라인 관리와 지속 교전을 함께 챙기세요. 신발은 올라프의 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 올라프는 (P)\'광전사의 분노\'로 체력이 낮을수록 생명력 흡수를 얻으니 점화로 회복을 줄이며 마무리하세요.' },
    '요네': { lv1: '요네가 (Q)\'필멸의 검\'으로 견제하며 중첩을 쌓아 띄우려고 해요. (Q)\'찌르기\'로 급소를 쳐서 체력을 회복하되, 요네의 (Q)\'필멸의 검\' 돌풍에 띄워지지 않게 옆으로 움직이세요. (P)\'사냥꾼의 길\' 때문에 추가 평타가 아프니 짧게 딜교환하세요.', lv3: '요네가 (E)\'영혼해방\'을 사용해 진입하면 육신으로 돌아가는 위치를 예측해 거리를 조절하세요. (Q)\'필멸의 검\'의 돌풍으로 띄워질 때는 (W)\'응수\'로 막아내면 기절시킬 수 있지만 (W)\'영혼 가르기\'에는 이동 불가 효과가 없어요. 기절한 요네에게 (E)\'대가의 검술\'로 빠르게 공격해 큰 피해를 입히세요.', lv6: '(R)\'대결투\'를 사용해 급소를 모두 터뜨리면 고정 피해로 요네를 빠르게 정리할 수 있어요. 요네가 (R)\'운명봉인\'으로 끌어당기려 할 때 (W)\'응수\'로 막아내면 역으로 기절시켜 킬각을 잡아요. 요네의 (E)\'영혼해방\'과 (R)\'운명봉인\' 연계가 강력하니 정글러가 올 때까지 라인을 적절히 당겨 주세요.', item: '첫 코어는 굶주린 히드라로 가서 광역 피해와 흡혈로 라인 관리와 지속 교전을 함께 챙기세요. 신발은 요네의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 라인 유지력을 높이고 순간이동을 통해 운영 주도권을 잡는 것이 중요해요.' },
    '요릭': { lv1: '요릭은 (Q)\'최후의 의식\'으로 기본 공격을 하며 무덤을 쌓고 (P)\'영혼의 길잡이\' 망령으로 압박해요. (Q)\'찌르기\'로 급소를 빠르게 치고 빠지며 무리한 교전을 피하고 거리 조절을 하세요. 요릭이 무덤을 많이 모아 망령을 여러 마리 소환하기 전에 짧게 딜교환을 하는 것이 좋아요.', lv3: '(E)\'애도의 안개\'를 맞으면 망령들이 몰려오니 주의하고 둔화가 걸린 채 오래 버티지 마세요. (W)\'망자의 진\' 벽에 막히면 벽을 공격해 파괴한 뒤 (E)\'대가의 검술\'로 공격을 이어가세요. 요릭의 (Q)\'최후의 의식\' 강화 공격이 빠진 타이밍에 (W)\'응수\'로 평타를 막아내며 진입해 급소를 치세요.', lv6: '(R)\'군도의 장송곡\'으로 소환된 마녀와 망령들이 함께 공격하면 매우 아프니 마녀를 먼저 정리하거나 요릭을 빠르게 제압하세요. (R)\'대결투\'를 사용해 요릭의 급소를 모두 터뜨려 고정 피해를 입히고 체력을 회복하며 싸우세요. 요릭이 마녀를 이용해 라인을 밀 때 (Q)\'찌르기\'로 미니언을 정리하며 정글 개입을 기다리세요.', item: '삼위일체와 판금 장화를 추천해요. 삼위일체의 체력과 공격 속도로 지속 싸움을 이끌고 판금 장화로 요릭의 기본 공격 피해를 줄이세요.', spell: '점멸과 점화를 추천해요. (Q)\'최후의 의식\'으로 회복하는 요릭의 체력을 점화로 억제해 확실하게 마무리하세요.' },
    '우디르': { lv1: '우디르가 (E)\'불길 쇄도\' 태세로 빠르게 다가와 첫 평타로 기절시키려 하니 적절한 거리를 유지하세요. (Q)\'찌르기\'로 짧게 딜교환을 하고 바로 빠져나오며 우디르의 접근을 견제하세요. (P)\'가교\' 효과로 평타 속도가 빨라진 우디르와 정면으로 오래 붙어 있으면 피해가 커요.', lv3: '우디르가 (E)\'불길 쇄도\'로 기절을 걸려고 할 때 (W)\'응수\'로 이를 막아내어 역으로 기절시키세요. 우디르가 (W)\'강철 갑옷\'을 켜서 보호막을 얻었을 때는 (E)\'대가의 검술\' 딜교환을 잠시 미루고 보호막이 사라질 때까지 기다리세요. (Q)\'야생 발톱\' 태세의 강력한 추가 피해가 들어오는 타이밍에는 (Q)\'찌르기\'로 빠르게 거리 조절을 하세요.', lv6: '(R)\'대결투\'를 사용해 우디르의 높은 체력을 고정 피해로 깎아내며 킬각을 보세요. 우디르가 (R)\'날개 돋친 폭풍\'을 켜서 주변에 둔화를 걸면 이동 속도가 느려지니 급소를 빠르게 가격하며 움직이세요. 우디르가 (E)\'불길 쇄도\'를 재사용해 이동 불가 효과에 면역이 되면 (W)\'응수\'의 기절이 통하지 않으니 주의하세요.', item: '삼위일체를 첫 코어로 가서 공격력과 체력을 챙기고 (Q)\'찌르기\' 이후 평타 딜교환 효율을 높이세요. 신발은 우디르의 기본 공격 피해를 줄여주는 판금 장화가 적합해요.', spell: '점멸과 점화를 추천해요. 우디르가 (W)\'강철 갑옷\'으로 체력을 회복하는 것을 방해하며 마무리 일격을 가하세요.' },
    '우르곳': { lv1: '우르곳은 (Q)\'부식성 폭약\'으로 둔화를 걸고 (P)\'화염의 메아리\'로 원거리 견제를 해요. 폭약의 낙하지점을 피해 이동하며 막타를 챙기고, (Q)\'찌르기\'로 짧게 진입해 급소를 쳐서 체력을 회복하세요. 무리하게 붙으면 평타 피해가 크니 짧은 딜교환 후 빠지세요.', lv3: '(E)\'경멸\' 돌진에 맞춰 (W)\'응수\'를 사용하면 우르곳을 기절시키고 주도권을 잡을 수 있어요. 우르곳이 (Q)\'부식성 폭약\'을 맞혀 (W)\'심판의 원\'을 켜면 둔화된 상태로 사격하니 빠르게 거리를 벌리세요. (E)\'경멸\'이 빠진 틈에 (E)\'대가의 검술\'을 활용해 빠르게 급소를 가격하고 빠지세요.', lv6: '(R)\'불사의 공포\' 섬광탄을 맞으면 체력이 낮을 때 제압되어 처형될 수 있으니 주의하세요. 우르곳의 (E)\'경멸\' 보호막이 사라지는 타이밍에 (R)\'대결투\'를 사용하여 빠르게 급소를 공략하세요. 정글러가 올 때 (W)\'응수\'로 (E)\'경멸\'을 막아내면 역으로 킬각을 잡기 편해요.', item: '삼위일체를 첫 코어로 가서 공격 속도와 체력을 보충해 지속 싸움 능력을 높이세요. 신발은 우르곳의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 우르곳의 체력이 높으므로 점화의 추가 피해로 (R)\'불사의 공포\' 처형선에 닿기 전에 빠르게 처치하세요.' },
    '워윅': { lv1: '워윅이 (Q)\'야수의 송곳니\'로 도약하며 체력을 회복하는 구간은 매우 강력하니 주의해야 해요. (Q)\'찌르기\'를 활용해 급소를 가격하며 피해를 주고, 워윅의 초반 맞딜에 휘말리지 않도록 (P)\'치명적인 검무\'의 이동 속도 증가를 이용해 거리를 조절하세요.', lv3: '워윅이 (E)\'원시의 포효\'로 공포를 걸려고 하면 (W)\'응수\'로 막아내거나 포효 범위 밖으로 벗어나세요. (W)\'피의 사냥\'은 체력이 낮은 적에게 워윅의 이동 속도와 공격 속도를 올려 주니 체력이 낮아졌을 때는 빠르게 딜교환을 마치고 빠지세요.', lv6: '워윅이 (R)\'무한의 구속\'을 사용해 제압하면 아무것도 할 수 없으니 정글러의 위치를 항상 확인하세요. (R)\'대결투\'를 사용하여 급소들을 모두 가격하며 체력을 회복하고, 워윅의 (P)\'끝없는 허기\' 회복을 고려해 라인을 적절히 관리하며 싸우세요.', item: '헤르메스의 발걸음과 몰락한 왕의 검을 추천해요. 헤르메스의 발걸음으로 마법 저항력을 챙기고 몰락한 왕의 검으로 맞딜 능력을 높이세요.', spell: '점멸과 점화를 추천해요. 점화로 워윅의 (Q)\'야수의 송곳니\'와 (P)\'끝없는 허기\'를 통한 체력 회복을 억제하세요.' },
    '이렐리아': { lv1: '이렐리아는 (Q)\'칼날 쇄도\'로 미니언을 타고 들어오며 체력을 회복하고 (P)\'아이오니아의 열정\' 중첩을 쌓기 쉬워요. 미니언의 체력이 낮을 때는 이렐리아가 돌진하지 못하도록 거리를 유지하며 (Q)\'찌르기\'로 견제하세요. 이렐리아가 미니언을 타고 접근할 때 (P)\'치명적인 검무\'의 급소를 노려 맞받아쳐야 해요.', lv3: '이렐리아의 (E)\'쌍검협무\'는 칼날이 돌아오며 기절을 일으키니 칼날이 모이는 길목을 잘 피하세요. 이렐리아가 (Q)\'칼날 쇄도\'로 들어올 때 (W)\'응수\'를 사용하여 피해를 막아내거나 (E)\'쌍검협무\'의 기절을 차단하세요. (W)\'저항의 춤\'을 사용하는 동안에는 무리하게 딜교환을 하지 말고 (E)\'대가의 검술\'로 공격 속도를 높이며 타이밍을 보세요.', lv6: '이렐리아의 (R)\'선봉진격검\'이 적중하면 칼날 결계가 생기고 결계를 통과할 때 피해와 둔화를 받으니 결계를 억지로 빠져나가려 하지 마세요. 이렐리아가 스킬로 (P)\'아이오니아의 열정\' 중첩을 쌓기 전에 (R)\'대결투\'를 사용하여 급소를 빠르게 가격하세요. 이렐리아가 (Q)\'칼날 쇄도\'로 빠져나가려 할 때 (Q)\'찌르기\'를 적절히 사용하여 추격하며 킬각을 잡으세요.', item: '첫 코어로 굶주린 히드라를 가서 체력 회복과 딜을 동시에 챙기세요. 신발은 이렐리아의 (E)\'쌍검협무\'와 (R)\'선봉진격검\'에 의한 군중 제어 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'칼날 쇄도\'의 체력 회복 효과를 줄이면서 확실하게 마무리할 수 있어요.' },
    '일라오이': { lv1: '일라오이는 (P)\'고대신의 예언자\'로 지형 근처에 촉수를 소환해 물리 피해를 주니 벽 근처를 피하세요. 1~2레벨에는 (Q)\'찌르기\'를 활용해 일라오이의 체력을 깎으며 (P)\'치명적인 검무\'의 급소를 노려보세요. 촉수가 없는 라인 중앙에서 싸우는 것이 좋아요.', lv3: '일라오이가 (E)\'영혼의 시험\'으로 내 영혼을 분리하면, 일라오이가 그 영혼을 때릴 때 피해 일부가 나에게 들어오고 영혼에서 멀어지면 내가 숙주가 되어 촉수의 표적이 돼요. 영혼이 분리된 동안에는 무리하게 싸우지 말고 벽에서 떨어진 채 지속시간을 버티세요. 일라오이가 (W)\'혹독한 가르침\'으로 도약하며 들어올 때 (W)\'응수\'로 공격을 막아내며 (E)\'대가의 검술\'로 급소를 가격하세요.', lv6: '일라오이가 (R)\'믿음의 도약\'을 쓰면 촉수가 소환되고 한동안 대상으로 지정할 수 없는 상태로 더 빠르게 후려치니 촉수 근처에서 싸우지 말고 거리를 벌리세요. (R)\'대결투\'를 사용해 급소를 모두 가격하며 체력을 회복하고 일라오이의 촉수 공격을 피하며 싸워야 해요. 궁극기 효과가 끝나 촉수가 다시 느려진 뒤에 (Q)\'찌르기\'로 진입하세요.', item: '몰락한 왕의 검을 첫 코어로 올려 공격 속도와 생명력 흡수를 챙기세요. 신발은 일라오이의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점멸로 벽 근처의 촉수 범위를 벗어나고, 촉수가 없는 곳에서 (R)\'대결투\'를 쓴 뒤 점화로 마무리 피해를 넣으세요.' },
    '자크': { lv1: '자크는 (Q)\'탄성 주먹\'으로 붙잡아 견제하고 (P)\'세포 분열\' 조각을 흡수해 체력을 회복해요. (Q)\'찌르기\'로 급소를 찌르며 짧게 딜교환하고, 자크가 조각을 주우러 오는 경로를 예측해 압박하세요. 상대의 팔이 뻗어오는 직선 경로에서 비켜나며 체력 차이를 벌리세요.', lv3: '(E)\'새총 발사\'로 날아오는 자크를 (W)\'응수\'로 막아내면 적을 기절시키고 역공할 수 있어요. 기절한 틈에 (E)\'대가의 검술\'과 평타를 섞어 빠르게 피해를 입히세요. (W)\'불안정 물질\'은 주변에 마법 피해를 주니 자크가 몸을 터뜨리려 하면 짧게 공격하고 뒤로 물러나세요.', lv6: '(R)\'대결투\'를 사용해 자크의 높은 체력을 무시하는 고정 피해를 입히면 킬각을 잡기 편해요. 자크가 (R)\'바운스!\'로 진입할 때 (W)\'응수\'로 충격을 막아 기절시키면 상대의 흐름을 완전히 끊을 수 있어요. 처치 후 (P)\'세포 분열\'로 갈라진 조각들을 빠르게 공격해 부활하지 못하게 처리하세요.', item: '굶주린 히드라를 첫 코어로 가서 생명력 흡수와 라인 푸쉬력을 챙기세요. 신발은 자크의 마법 피해를 줄이고 강인함을 제공하는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'세포 분열\'의 체력 회복 효과를 감소시켜 더 빠르게 처치하세요.' },
    '자헨': { lv1: '자헨은 (Q)\'다르킨의 글레이브\'로 두 번 공격하며 체력을 회복하므로 긴 평타 교환은 피하세요. (Q)\'찌르기\'로 급소를 빠르게 가격하고 빠지는 짧은 딜교환을 반복하세요. (P)\'전쟁 단련\' 중첩이 쌓이면 자헨의 공격력이 강해지니 주의하세요.', lv3: '자헨이 (W)\'공포의 귀환\'으로 끌어당기려 할 때 (W)\'응수\'로 막아 기절시키세요. (E)\'찬란한 쇄도\'로 진입하는 타이밍에 (E)\'대가의 검술\'로 빠르게 대응하며 급소를 치세요. (Q)\'다르킨의 글레이브\' 재사용으로 띄우는 공격을 (W)\'응수\'로 받아내면 흐름을 가져올 수 있어요.', lv6: '(R)\'단호한 판결\'을 사용해 날아오르는 자헨의 낙하 지점에서 빠르게 벗어나세요. (R)\'대결투\'를 켜고 급소를 빠르게 모두 가격하여 (P)\'전쟁 단련\'의 부활 효과가 발동하기 전에 처치하세요. 정글러가 올 때 자헨의 (E)\'찬란한 쇄도\'가 빠졌는지 확인하고 진입하세요.', item: '첫 코어는 굶주린 히드라로 가서 광역 피해와 흡혈로 라인 관리와 지속 교전을 함께 챙기세요. 신발은 자헨의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 자헨의 (Q)\'다르킨의 글레이브\'와 (R)\'단호한 판결\'을 통한 체력 회복을 점화의 치유 감소로 억제하세요.' },
    '잭스': { lv1: '잭스는 (P)\'가차없는 맹공\'으로 공격 속도를 높여 지속 싸움을 유도해요. (Q)\'찌르기\'로 급소를 찌르고 빠르게 거리를 벌려 짧은 교전 위주로 플레이하세요. 잭스가 (W)\'무기 강화\'를 켜고 들어올 때 정면으로 맞붙지 말고 빠르게 빠지세요.', lv3: '잭스가 (E)\'반격\'을 켜면 즉시 공격을 멈추고 거리 조절을 하세요. (E)\'반격\'의 기절 효과를 (W)\'응수\'로 막아내면 역으로 기절을 시켜 교전을 주도할 수 있어요. (E)\'반격\'이 끝난 직후에 (E)\'대가의 검술\'로 빠르게 공격해 피해를 입히세요.', lv6: '(R)\'대결투\'를 사용해 드러난 모든 급소를 빠르게 가격하면 고정 피해로 체력을 크게 깎을 수 있어요. 잭스가 (R)\'무기의 달인\'으로 방어력과 마법 저항력을 높였을 때는 무리하게 붙지 말고 급소만 찌르며 괴롭히세요. (Q)\'도약 공격\'으로 들어오는 타이밍에 맞춰 (W)\'응수\'를 써서 변수를 차단하세요.', item: '첫 코어는 굶주린 히드라로 가서 광역 피해와 흡혈로 라인 관리와 지속 교전을 함께 챙기세요. 신발은 잭스의 기본 공격 피해를 줄여 주는 판금 장화를 맞추세요.', spell: '점멸과 순간이동을 추천해요. 라인 복귀를 빠르게 하여 주도권을 잡고 (R)\'대결투\' 이후 추격이나 도주에 점멸을 활용하세요.' },
    '제이스': { lv1: '제이스가 캐논 형태로 (Q)\'전격 폭발\'을 사용하여 멀리서 견제하니 투사체 궤적을 잘 살피며 피하세요. (Q)\'전격 폭발\'은 미니언에 맞아도 그 자리에서 폭발해 주변에 피해를 주니 미니언 바로 뒤에 붙어 서지 말고 (Q)\'찌르기\'로 진입할 타이밍을 노려야 해요. 제이스가 해머로 바꿔서 (Q)\'하늘로!\'를 쓰며 들어오면 빠르게 대응하세요.', lv3: '제이스가 해머로 (E)\'천둥 강타\'를 쓸 때 (W)\'응수\'로 막아내세요. 캐논 형태의 (Q)\'전격 폭발\'은 사거리가 나보다 길어 무리하게 들어가지 말고 투사체를 피하며 거리를 좁히세요. 제이스가 해머로 바꾼 직후 (E)\'대가의 검술\'로 딜교환을 시작하세요.', lv6: '제이스가 (R)\'머큐리 캐논\'을 사용하여 방어력을 깎기 전에 (R)\'대결투\'를 켜고 급소를 빠르게 가격하세요. 제이스가 (E)\'가속 관문\'을 통해 도망가려 하면 (Q)\'찌르기\'를 사용하여 추격해야 해요. 제이스의 스킬이 빠진 타이밍에 (R)\'대결투\'를 사용하면 안정적으로 킬을 노릴 수 있어요.', item: '첫 코어는 굶주린 히드라로 가서 광역 피해와 흡혈로 라인 관리와 지속 교전을 함께 챙기세요. 신발은 제이스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 제이스가 스킬을 쓰고 도망치려 할 때 점화를 사용해 킬을 가져오세요.' },
    '초가스': { lv1: '초가스는 (E)\'날카로운 가시\'로 평타마다 전방에 피해와 둔화를 주니 정면에 서지 마세요. (Q)\'파열\'이 지면을 파열시키며 공중으로 띄우는 표시를 보고 범위 밖으로 이동하며 거리를 조절해요. 초반에는 (Q)\'찌르기\'로 급소를 노려 (P)\'치명적인 검무\'의 효과를 활용하며 성장을 준비하세요.', lv3: '초가스가 (W)\'흉포한 울부짖음\'을 쓰기 전에 옆으로 피하여 침묵에 걸리지 않도록 하세요. (Q)\'파열\'이 들어오는 타이밍에 (W)\'응수\'를 사용하여 공중으로 뜨는 것을 막고 초가스를 기절시키는 것이 중요해요. 초가스의 스킬이 빠진 뒤에는 (E)\'대가의 검술\'을 섞어 빠르게 급소를 가격하며 딜교환을 해요.', lv6: '초가스가 (R)\'포식\'을 사용하면 큰 고정 피해를 입고 몸집을 키우니 체력이 낮을 때는 가까이 있지 마세요. (R)\'대결투\'를 사용해 모든 급소를 가격하면 초가스의 높은 체력을 상쇄하며 킬을 노릴 수 있어요. 초가스가 (R)\'포식\'을 미니언에 사용하여 성장하는 동안 (Q)\'찌르기\'로 급소를 계속 찔러 압박하세요.', item: '초가스의 마법 피해를 견디기 위해 헤르메스의 발걸음을 먼저 구매하세요. 첫 코어 아이템으로는 전투 지속력을 높여주는 몰락한 왕의 검을 추천해요.', spell: '점멸과 점화를 사용하세요. 점화로 초가스의 체력을 깎아 마무리 피해를 입히고 대응 능력을 높여요.' },
    '카밀': { lv1: '카밀은 (P)\'적응형 방어 체계\'로 보호막을 얻으며 (Q)\'정확성 프로토콜\'로 추가 피해를 입혀요. 보호막이 있을 때는 (Q)\'찌르기\'를 사용해 무리하게 딜교하기보다 거리를 조절하세요. 1~2레벨에는 카밀의 강화 평타를 피하며 (P)\'치명적인 검무\'의 급소를 노리는 데 집중하세요.', lv3: '카밀의 (W)\'전술적 휩쓸기\' 바깥쪽 절반에 맞으면 둔화되고 카밀이 체력을 회복하니 원뿔 안쪽으로 파고드세요. 카밀이 (E)\'갈고리 발사\'로 도약해 기절을 시키려 할 때 (W)\'응수\'를 사용하여 카밀을 기절시키세요. (E)\'대가의 검술\'로 카밀을 둔화시킨 뒤 (P)\'치명적인 검무\'의 급소를 노려 딜교환을 하세요.', lv6: '카밀의 (R)\'마법공학 최후통첩\'에 갇히면 탈출할 수 없지만 이동 불가 효과는 아니니, (W)\'응수\'는 (E)\'갈고리 발사\'의 기절을 막는 데 아껴 두었다가 역으로 기절시키세요. (R)\'대결투\'를 사용해 급소를 모두 가격하며 카밀의 마법 피해에 대응하며 싸우세요. 카밀이 (E)\'갈고리 발사\'를 이용해 벽을 타고 들어오는 상황을 대비해 와드를 설치하고 정글러의 개입을 조심하세요.', item: '첫 코어로 굶주린 히드라를 가서 공격력과 생명력 흡수를 챙기세요. 신발은 카밀의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 카밀은 (W)\'전술적 휩쓸기\'로 체력을 회복하니 점화의 치유 감소 효과가 유용해요.' },
    '카사딘': { lv1: '(Q)\'무의 구체\' 견제를 최소화하며 거리 조절을 하세요. (Q)\'찌르기\'를 활용해 빠르게 접근하여 급소를 타격하고 피해를 입히세요. 초반에는 적극적으로 붙어 압박하는 것이 좋아요.', lv3: '(E)\'힘의 파동\'이 빠진 것을 확인한 뒤 (Q)\'찌르기\'로 진입하세요. (E)\'힘의 파동\'은 둔화라 (W)\'응수\'로 기절시키기는 어려우니 (W)\'응수\'는 (Q)\'무의 구체\' 같은 공격을 막는 데 쓰세요. (E)\'대가의 검술\'을 사용해 빠르게 급소를 가격하고 딜교환을 마무리하세요.', lv6: '(R)\'대결투\'를 사용해 급소를 빠르게 드러내지만 (R)\'균열 이동\'으로 도망칠 수 있으니 주의하세요. 라인을 밀어넣어 상대의 이동 경로를 제한하고 킬각을 노리세요. 정글 개입이 올 수 있으니 (W)\'응수\'를 아껴두었다가 결정적인 순간에 사용하세요.', item: '헤르메스의 발걸음과 삼위일체를 추천해요. 마법 피해를 줄이고 (E)\'힘의 파동\' 둔화 시간을 줄이며 강력한 공격력과 체력을 얻기 위해서예요.', spell: '점멸과 점화예요. 순간적인 거리 좁히기로 킬각을 잡고 강력한 피해를 입히기 위해서예요.' },
    '카시오페아': { lv1: '1~2레벨에는 (Q)\'맹독 폭발\' 견제를 최대한 피하며 경험치를 챙기세요. (Q)\'찌르기\'로 무리하게 진입하기보다 미니언 뒤에서 버티며 급소가 나타나면 짧게 딜교환을 하세요.', lv3: '상대가 (W)\'독기의 늪\'을 사용하면 그 안에서는 (Q)\'찌르기\'를 쓸 수 없으니 독구름 밖에서 진입하세요. 6레벨 전 카시오페아에게는 이동 불가 효과가 없으니 (W)\'응수\'는 (E)\'쌍독니\' 같은 공격을 막는 데 쓰고, (E)\'대가의 검술\'로 둔화를 걸며 딜교환을 해요.', lv6: '(R)\'대결투\'를 켜고 진입할 때 상대의 (R)\'석화의 응시\'를 (W)\'응수\'로 막아 역으로 기절시키는 것이 핵심이에요. (W)\'응수\'가 빠져 있다면 (R)\'석화의 응시\'를 쓰는 순간 등을 돌려 기절 대신 둔화만 받은 뒤 다시 붙어 급소를 타격하세요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 가세요. 마법 저항력을 높이고 보호막으로 상대의 폭발적인 마법 피해를 견뎌낼 수 있어요.', spell: '점멸과 점화를 추천해요. (E)\'쌍독니\'를 통한 상대의 체력 회복을 억제하고 킬 결정력을 높이기 위해서예요.' },
    '케넨': { lv1: '케넨은 (Q)\'천둥의 표창\'을 던져서 멀리서 견제하며 (P)\'폭풍의 표식\'을 쌓으려 해요. 표창은 투사체이므로 미니언 뒤에 숨어서 피해를 줄이는 것이 좋아요. 케넨이 표창을 맞히지 못했을 때 (Q)\'찌르기\'로 파고들어 급소를 노리며 압박하세요.', lv3: '케넨이 (E)\'번개 질주\'로 진입하며 표식을 쌓을 때 (W)\'응수\'를 사용하여 케넨의 기절을 막아내야 해요. 케넨이 (W)\'전류 방출\'로 표식을 터뜨리며 들어올 때 거리를 조절하며 스킬을 피하세요. 케넨의 주요 스킬이 빠진 타이밍에 (E)\'대가의 검술\'을 활용해 급소를 빠르게 공략하세요.', lv6: '케넨이 (R)\'날카로운 소용돌이\'를 사용하면 범위 내에서 큰 마법 피해를 입으니 그 안에서 오래 머물지 마세요. 케넨이 궁극기로 진입할 때 (W)\'응수\'를 미리 준비해 기절을 막아내면 (R)\'대결투\'로 역습할 수 있어요. 케넨이 스킬을 모두 소모한 시점에 급소를 가격하며 킬각을 노리세요.', item: '케넨의 마법 피해를 견디기 위해 헤르메스의 발걸음을 선택하세요. 첫 코어 아이템으로는 생명력 흡수와 공격력을 챙길 수 있는 굶주린 히드라를 추천해요.', spell: '점멸과 정화를 추천해요. 케넨의 (P)\'폭풍의 표식\'이나 궁극기로 발생하는 기절을 정화로 빠르게 풀 수 있어요.' },
    '케일': { lv1: '케일은 (P)\'거룩한 승천\'이 오르기 전까지 몸싸움이 약한 구간이에요. (Q)\'광휘의 일격\'의 둔화와 방어력 감소를 조심하며 (Q)\'찌르기\'를 이용해 적극적으로 압박하세요. 첫 웨이브를 빠르게 정리하며 케일이 CS를 먹을 때마다 거리를 좁히는 것이 좋아요.', lv3: '케일이 (E)\'화염주문검\'을 사용해 잃은 체력에 비례한 피해를 입히니 체력 관리에 주의하세요. (W)\'천상의 축복\'으로 회복하며 도망가는 케일에게 (E)\'대가의 검술\'을 맞춰 둔화를 걸고 추격하세요. (Q)\'광휘의 일격\'의 궤적을 (W)\'응수\'로 받아내며 딜교환을 시도하면 좋아요.', lv6: '케일이 (R)\'신성한 심판\'으로 무적 상태가 되면 킬을 내기 어려우니 궁극기 사용 여부를 꼭 확인하세요. 케일의 궁극기가 빠진 뒤 (R)\'대결투\'를 사용해 급소를 빠르게 가격하면 킬을 가져올 수 있어요. 라인을 밀어 넣으며 케일의 성장을 억제하고 정글러의 개입을 유도하세요.', item: '첫 코어로 몰락한 왕의 검을 가서 공격 속도와 생명력 흡수를 챙기세요. 신발은 케일의 마법 피해를 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 케일이 강해지기 전에 점화로 압박을 넣어 격차를 벌리세요.' },
    '코그모': { lv1: '코그모의 (Q)\'부식성 침\'으로 방어력이 깎이면 피해가 더 많이 들어오니 주의하며 거리 조절을 해요. (Q)\'찌르기\'를 사용해 빠르게 접근하며 체력 손실을 최소화하고 효율적으로 딜교환을 시도하세요.', lv3: '(E)\'공허의 분비물\' 흔적은 둔화라 (W)\'응수\'로 기절시킬 수 없으니 흔적 위를 피해 움직이세요. (W)\'응수\'는 (Q)\'부식성 침\' 같은 공격을 막는 데 쓰고, 빈틈에 (E)\'대가의 검술\'로 급소를 가격해 큰 피해를 입히세요.', lv6: '(R)\'대결투\'를 사용하여 코그모의 급소를 빠르게 드러내고 강하게 압박하며 킬각을 잡으세요. 체력이 낮을 때 (R)\'살아있는 곡사포\'의 강력한 마법 피해가 들어오므로 체력 관리를 하며 진입하세요.', item: '헤르메스의 발걸음과 굶주린 히드라를 선택해요. 마법 저항력과 둔화 감소로 견제를 버티고 생명력 흡수로 라인 유지력을 높여요.', spell: '점멸과 순간이동을 선택해요. 원거리 챔피언을 추격하기 위해 점멸이 필요하며 라인 복귀를 위해 순간이동을 사용하세요.' },
    '코르키': { lv1: '(Q)\'인광탄\'은 범위 스킬이라 미니언 뒤에 서도 피해를 받으니 낙하 지점을 보고 옆으로 움직여 피하세요. (Q)\'찌르기\'로 무리하게 진입하기보다 급소가 드러나는 타이밍에만 짧게 딜교환을 시도하세요. 초반에는 거리 조절로 피해를 줄이는 것이 중요해요.', lv3: '상대가 (W)\'발키리\'로 거리를 벌리려 할 때 (Q)\'찌르기\'로 빠르게 추격하세요. (E)\'개틀링 건\'의 공격을 (W)\'응수\'로 막아내어 피해를 무시하고 접근하세요. (E)\'대가의 검술\'을 사용하여 빠르게 연속으로 공격해 급소를 터뜨리세요.', lv6: '(W)\'발키리\'가 사용된 시점에 (R)\'대결투\'를 켜고 빠르게 진입해 급소를 가격하세요. (R)\'미사일 폭격\'의 큰 미사일이 날아올 때는 잠시 거리를 벌리거나 (W)\'응수\'로 대응하세요. 라인을 밀어넣은 뒤 정글러와 함께 좁은 길목에서 압박하세요.', item: '헤르메스의 발걸음과 삼위일체를 선택하세요. 마법 저항력으로 (Q)\'인광탄\' 피해를 줄이고 공격력과 체력을 높여 교전 능력을 올리세요.', spell: '점멸과 순간이동을 추천해요. 원거리 챔피언을 상대하므로 빠른 라인 복귀와 합류가 필요해요.' },
    '퀸': { lv1: '퀸은 (P)\'매사냥\' 표식이 붙은 대상에게 강한 평타 견제를 하니, 표식이 사라질 때까지 사리를 하세요. (E)\'공중제비\'로 밀어내며 거리를 벌리려 하므로, 무리하게 쫓지 말고 미니언 뒤에서 피해를 최소화하며 (Q)\'찌르기\' 거리만 재세요.', lv3: '(E)\'공중제비\'의 넉백과 둔화를 (W)\'응수\'로 막아내면 퀸을 기절시킬 수 있어요. (E)\'대가의 검술\'을 켜고 (Q)\'찌르기\'로 빠르게 붙은 뒤, 퀸이 물러나기 전에 급소를 쳐서 체력을 회복하세요. (Q)\'실명 공격\'에 맞으면 시야가 좁아지니 상대의 위치를 계속 확인하세요.', lv6: '(R)\'대결투\'를 사용해 퀸의 급소를 모두 치면 큰 고정 피해를 입혀 한 번에 처치할 수 있어요. 퀸이 (R)\'후방 지원\'으로 빠르게 이동하며 로밍을 시도하므로, 라인을 밀어넣고 정글러와 함께 대처하세요. (W)\'응수\'로 (E)\'공중제비\'를 막아 기절시킨 뒤 (R)\'대결투\'를 연계하면 확실한 킬각이 나와요.', item: '삼위일체를 가서 공격력과 체력을 챙기고 (Q)\'찌르기\' 이후 빠른 평타 딜교를 하세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 적합해요.', spell: '점멸과 순간이동을 추천해요. 퀸의 강한 푸쉬력에 대응해 빠르게 라인에 복귀하고 운영을 하세요.' },
    '크산테': { lv1: '크산테는 (Q)\'엔토포 타격\'으로 둔화를 걸며 견제하니 거리를 조절하세요. 중첩이 쌓여 충격파가 발동하기 전에 뒤로 물러나야 해요. (Q)\'찌르기\'를 활용해 미니언과 함께 크산테를 압박하며 급소를 노릴 준비를 하세요.', lv3: '크산테가 (W)\'길을 여는 자\'로 돌진하며 기절을 시도할 때 (W)\'응수\'를 사용하여 기절을 막아내고 역으로 기절시키세요. (W)\'길을 여는 자\'가 저지 불가 상태일 때는 무리하게 맞서지 말고 (E)\'대가의 검술\'을 준비하세요. 크산테의 (E)\'발놀림\' 보호막이 끝나는 타이밍에 맞춰 급소를 가격하면 좋아요.', lv6: '크산테가 (R)\'총공세\'를 사용해 방어력이 낮아진 상태가 되면 (R)\'대결투\'를 켜고 급소를 빠르게 가격해 몰아붙이세요. (R)\'총공세\'의 돌진으로 벽 너머로 밀려나면 거리가 멀어지니 (Q)\'찌르기\'로 위치를 잘 잡아야 해요. 크산테의 스킬이 빠진 뒤에 라인을 관리하며 정글러의 개입에 대비하세요.', item: '첫 코어는 굶주린 히드라로 가서 광역 피해와 흡혈로 라인 관리와 지속 교전을 함께 챙기세요. 신발은 크산테의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화는 크산테의 체력 회복 효과를 감소시켜 킬각을 잡는 데 도움을 줘요.' },
    '클레드': { lv1: '클레드는 (P)\'겁쟁이 도마뱀 스칼\'이 피해를 대신 받아 초반 교전이 강하니 무리하게 붙지 마세요. (Q)\'덫날리기\'에 맞은 상태로 클레드 근처에 있으면 끌려가며 추가 피해를 입으니 거리 조절을 하며 (Q)\'찌르기\'로 급소를 가격하세요. 첫 웨이브는 최대한 사리며 상대의 스칼 체력을 깎는 데 집중하세요.', lv3: '(Q)\'덫날리기\'로 끌어당기려는 타이밍에 (W)\'응수\'를 사용해 공격을 막아내고 기절을 노리세요. (W)\'버럭버럭\'이 켜진 동안에는 평타 싸움에서 밀리니 (E)\'대가의 검술\'을 사용해 빠르게 급소만 치고 빠지는 딜교환을 하세요. 클레드가 (E)\'이랴!\'를 사용해 진입했다면 적절한 거리를 유지하며 대응하세요.', lv6: '(R)\'돌겨어어억!!!\'으로 돌진해오는 클레드의 경로에서 벗어나거나 (W)\'응수\'로 쳐내어 진입을 차단하세요. 스칼에서 내려온 클레드에게 (R)\'대결투\'를 사용하여 빠르게 급소를 모두 가격해 마무리하세요. 라인을 당겨서 (R)\'돌겨어어억!!!\'을 통한 다이브 위험을 줄이고 정글러의 개입을 기다리세요.', item: '삼위일체를 첫 코어로 가서 공격력과 체력 그리고 공격 속도를 챙겨 지속 교전 능력을 높이세요. 신발은 클레드의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점멸로 (Q)\'덫날리기\'에 끌려가기 전에 거리를 벌리고, 스칼에서 내려 체력이 낮아진 클레드를 점화로 확실하게 처치하세요.' },
    '탐켄치': { lv1: '탐 켄치는 (Q)\'혀 채찍\'으로 견제하며 (P)\'절대 미각\' 중첩을 쌓으니 미니언 뒤에 서서 혀를 막아내세요. 중첩이 쌓이면 기절에 걸리니 짧게 교환하고 (Q)\'찌르기\'로 급소를 찔러 체력을 회복하며 거리 조절을 하세요. 1~2레벨 구간에는 무리하게 붙지 말고 급소만 툭툭 쳐주세요.', lv3: '탐 켄치가 (W)\'심연 잠수\'로 들어올 때 (W)\'응수\'를 사용해 기절시키면 역전의 기회를 잡을 수 있어요. (E)\'두꺼운 피부\' 보호막이 활성화된 동안에는 딜을 아끼고, 보호막이 사라진 직후에 (E)\'대가의 검술\'로 치명타 피해를 입히세요. (Q)\'혀 채찍\'의 기절이 들어오기 전에 빠르게 딜교환을 마치고 빠지세요.', lv6: '(R)\'대결투\'를 사용해 탐 켄치의 높은 체력을 고정 피해로 빠르게 깎아내세요. (P)\'절대 미각\' 중첩이 쌓인 상태에서 가까이 있으면 (R)\'집어삼키기\'에 먹혀 피해를 입으니 주의하세요. 정글러가 올 때 (W)\'응수\'로 적의 진입을 끊어내며 라인 주도권을 유지하세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 생명력 흡수로 유지력을 높이며 탐 켄치를 상대하세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 탐 켄치의 (E)\'두꺼운 피부\' 회복량을 줄여서 잡으세요.' },
    '트런들': { lv1: '트런들은 (Q)\'깨물기\'로 공격력을 훔치며 초반 교환에서 강한 모습을 보여요. (Q)\'깨물기\'를 맞으면 공격력이 줄어드니 무리하게 맞대결하지 말고 거리를 유지하세요. (P)\'치명적인 검무\'의 급소를 찔러 체력을 회복하며 버티는 것이 중요해요.', lv3: '트런들이 (E)\'얼음 기둥\'으로 길을 막거나 뒤로 밀어낼 때 (W)\'응수\'로 이동 불가 효과를 막아내는 것이 핵심이에요. 트런들이 (W)\'얼음 왕국\'을 사용하면 그 영역 안에서는 회복량이 늘어나니 영역 밖에서 (E)\'대가의 검술\'로 딜교환을 시도하세요. 상대의 (Q)\'깨물기\' 둔화가 빠진 타이밍을 노려 급소를 공략해요.', lv6: '트런들이 (R)\'진압\'을 사용하여 방어력을 훔치면 딜교환이 힘들어지니 궁극기를 사용한 직후에는 거리를 두세요. (R)\'대결투\'로 모든 급소를 가격하여 고정 피해를 입히고 (P)\'치명적인 검무\'의 회복 효과를 활용해 전투를 이어가세요. 트런들이 (P)\'헌납\'으로 체력을 회복하지 못하도록 미니언이 없는 곳에서 싸우는 것이 좋아요.', item: '판금 장화와 몰락한 왕의 검을 추천해요. 판금 장화는 트런들의 기본 공격 피해를 줄여주고 몰락한 왕의 검은 전투 지속력을 높여줘요.', spell: '점멸과 점화를 추천해요. 점화로 트런들의 (P)\'헌납\'과 (W)\'얼음 왕국\'에 의한 체력 회복을 억제하며 킬을 노리세요.' },
    '트린다미어': { lv1: '트린다미어는 (P)\'격노\'로 분노를 쌓아 치명타 확률을 높이고 (Q)\'피의 갈망\'으로 체력을 회복해요. (E)\'회전 베기\'로 진입하는 타이밍에 맞춰 거리를 조절하고, 상대가 스킬을 헛썼을 때 (Q)\'찌르기\'로 짧게 딜교환을 하세요. 첫 웨이브부터 무리하게 붙기보다 급소를 가격해 체력을 회복하며 버티세요.', lv3: '(W)\'조롱의 외침\'에 걸려 등을 돌리면 둔화되니 정면으로 맞서며 (W)\'응수\'로 상대의 공격을 막아 피해를 줄이세요. (E)\'회전 베기\'가 들어오는 경로를 미리 파악해 (W)\'응수\'로 받아내거나 (Q)\'찌르기\'로 빠르게 위치를 옮겨 피하세요. (E)\'대가의 검술\'로 연속 공격하여 급소를 맞히고 빠르게 빠져나오세요.', lv6: '(R)\'불사의 분노\'가 켜진 동안에는 체력이 닳지 않으니 (R)\'대결투\'를 바로 쓰지 말고 지속시간이 끝날 때까지 기다리세요. (R)\'불사의 분노\'가 끝나는 시점에 맞춰 급소를 빠르게 가격해 고정 피해를 입히고 처치하세요. 라인을 당겨서 정글 개입을 유도하고 (R)\'대결투\'의 광역 치유 효과로 아군과 함께 생존력을 높이세요.', item: '삼위일체를 첫 코어로 선택해 공격력과 체력을 챙기고 빠른 공격 속도로 급소를 공략하세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (Q)\'피의 갈망\'을 통한 트린다미어의 체력 회복을 억제하고 킬각을 잡기 위해 점화가 필요해요.' },
    '티모': { lv1: '티모는 (E)\'맹독 다트\'로 지속 피해를 주고 (Q)\'실명 다트\'로 실명시키며 괴롭혀요. (Q)\'찌르기\'로 미니언을 빠르게 정리하며 최대한 맞지 않게 거리 조절을 하세요. 수풀 근처에서는 티모가 (P)\'유격 전투\'로 숨을 수 있으니 시야 확보에 신경 쓰세요.', lv3: '티모의 (Q)\'실명 다트\'가 빠진 것을 확인하고 (Q)\'찌르기\'로 빠르게 진입하세요. (E)\'대가의 검술\'의 첫 공격 둔화로 티모가 도망치기 어렵게 만들며 급소를 가격하세요. (W)\'응수\'는 (Q)\'실명 다트\' 같은 공격을 막는 데 아껴 두세요.', lv6: '(R)\'유독성 함정\'을 밟으면 둔화와 피해를 입으니 버섯 위치를 기억하며 접근하세요. 티모가 도망가기 전에 (R)\'대결투\'를 사용해 네 군데의 급소를 빠르게 가격하고 고정 피해를 입히세요. 라인을 밀어 티모를 포탑으로 몰아넣으면 (R)\'대결투\'의 명중률을 높이기 편해요.', item: '삼위일체를 첫 코어로 선택해 공격력과 체력을 보충하고 빠른 진입을 준비하세요. 신발은 (R)\'유독성 함정\'의 둔화 지속 시간을 줄이고 마법 저항력을 높여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 티모는 체력이 매우 낮으므로 점화의 추가 피해로 (R)\'대결투\'와 함께 빠르게 마무리하세요.' },
    '판테온': { lv1: '판테온은 (Q)\'혜성의 창\'을 던져서 견제하고 (P)\'필멸자의 의지\'를 쌓으며 압박해요. (Q)\'혜성의 창\'이 빠진 직후에 (Q)\'찌르기\'로 짧게 딜교환을 시도하세요. 초반에는 판테온의 압박이 강하니 무리하게 맞딜을 하기보다 거리 조절에 집중해요.', lv3: '판테온이 (W)\'방호의 도약\'으로 돌진할 때 (W)\'응수\'를 사용해 기절을 막고 역으로 기절시키세요. (E)\'방패 돌격\'을 켠 동안에는 정면에서 딜을 넣지 말고 옆으로 돌아가서 (E)\'대가의 검술\'을 활용하세요. 판테온의 주요 스킬이 빠진 타이밍에 (Q)\'찌르기\'와 (E)\'대가의 검술\'로 급소를 노려야 해요.', lv6: '판테온이 (R)\'거대 유성\'을 사용하여 다른 라인으로 지원을 갈 수 있으니 미니맵을 잘 확인하세요. (R)\'대결투\'를 사용해 급소를 모두 가격하면 판테온의 체력이 낮을 때 확실하게 킬을 낼 수 있어요. 판테온의 (E)\'방패 돌격\'이 끝난 직후 (R)\'대결투\'로 몰아붙이는 것이 좋아요.', item: '첫 코어로 굶주린 히드라를 가서 라인 푸시와 생명력 흡수를 챙기세요. 신발은 판테온의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 판테온의 체력이 낮을 때 킬각을 확실히 잡으세요.' },
    '피들스틱': { lv1: '부쉬에서 갑자기 튀어나오는 (Q)\'공포\'를 맞지 않도록 시야 확보와 거리 조절에 집중하세요. (Q)\'찌르기\'로 미니언을 챙기며 (P)\'치명적인 검무\'의 급소를 타격해 체력을 관리하는 것이 좋아요. 상대의 견제를 피하며 안정적으로 파밍을 진행하세요.', lv3: '피들스틱이 (E)\'수확\'으로 둔화와 침묵을 걸려고 할 때 (W)\'응수\'로 막아내거나 범위 중심을 벗어나 침묵을 피하세요. 피들스틱이 (W)\'풍작\'을 쓰는 동안은 지속 피해가 들어오니 범위 밖으로 움직이세요. 두 스킬이 빠진 뒤 (E)\'대가의 검술\'로 접근해 딜교환을 시도하세요.', lv6: '(R)\'대결투\'를 사용하여 급소를 모두 가격해 폭발적인 피해를 입히고 킬을 노려보세요. 부쉬에서 피들스틱이 (R)\'까마귀 폭풍\'을 사용하며 진입할 수 있으니 항상 와딩을 하며 주의해야 해요. 상대의 궁극기 범위를 확인하며 라인을 관리하고 정글러의 위치도 살피세요.', item: '헤르메스의 발걸음과 굶주린 히드라를 선택해요. 헤르메스의 발걸음으로 마법 저항력과 강인함을 챙기고 굶주린 히드라로 공격력과 생명력 흡수를 얻으세요.', spell: '점멸과 점화를 추천해요. 피들스틱은 (W)\'풍작\'으로 체력을 회복하니 점화로 회복을 줄이고, 점멸로 (Q)\'공포\' 사거리 밖으로 빠지거나 거리를 좁히세요.' },
    '하이머딩거': { lv1: '하이머딩거가 (Q)\'H-28 G 진화형 포탑\'을 설치해 라인을 장악하니 1~2레벨에는 무리하게 붙지 마세요. 포탑의 공격을 견디며 막타만 챙기다가, 상대가 포탑 설치를 위해 앞으로 나올 때 (Q)\'찌르기\'로 짧게 진입해 피해를 입히세요. 포탑을 하나씩 제거하며 상대의 설치 공간을 없애는 게 중요해요.', lv3: '(E)\'CH-2 전자폭풍 수류탄\'의 기절 효과를 (W)\'응수\'로 막아내면 상대를 기절시키고 역습할 기회가 생겨요. (W)\'마법공학 초소형 로켓\'은 처음 적중한 적에게 피해를 주니 미니언 뒤에 숨어 피해를 최소화하세요. (E)\'대가의 검술\'을 켜고 빠르게 접근해 급소를 쳐야 포탑의 지속 피해를 덜 받아요.', lv6: '(R)\'업그레이드!!!\'로 강화된 수류탄이나 포탑은 피해가 매우 크니 사용 직후의 움직임을 주의하세요. 상대의 (E)\'CH-2 전자폭풍 수류탄\'이 빠진 타이밍에 (R)\'대결투\'를 켜고 빠르게 진입해 급소를 모두 가격하세요. 포탑이 너무 많을 때는 무리하게 들어가지 말고 정글러를 불러 함께 포탑부터 제거하세요.', item: '맬모셔스의 아귀를 가서 마법 저항력을 챙기고 생명선 보호막으로 폭발적인 피해를 버티세요. 신발은 수류탄의 기절 지속 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 한번 거리를 좁히면 하이머딩거는 도주기가 없으므로 점화로 빠르게 마무리하세요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_fiora);
if (typeof module !== 'undefined') module.exports = top_fiora;
